// Üretilen dosya: tool/ozgun/uret.py. Teknoloji · Robotik, sensörler ve otomasyon (kolay).
const ozTechnology10Kolay = <(String, String, List<String>, String)>[
  ('Fransız mucit Jacques de Vaucanson\'un 1739\'da sergilediği ve yediği tahılı "sindiriyormuş" gibi görünen ünlü otomatı hangi hayvan biçimindeydi?', 'Ördek', ['Tavus kuşu', 'Kaplumbağa', 'Tilki'], 'Vaucanson\'un \'sindiren ördeği\' kanat çırpıp tahıl yiyor ve dışkı bırakıyormuş gibi görünüyordu. Gerçekte dışkı önceden gizli bir bölmeye konuyordu.'),
  ('İskenderiyeli Heron\'un tapınaklar için tasarladığı, içine sikke atılınca belli miktar kutsal su veren düzenek, bugün hangi aygıtın öncüsü sayılır?', 'Otomatik satış makinesi', ['Hidrolik pres', 'Su basıncıyla çalışan otomatik kapı', 'Basınçlı kahve makinesi'], 'Atılan sikke bir kaldıracın ucundaki tabağa düşer, kaldıraç bir vanayı kısa süre açar ve su akar. Bu yüzden ilk otomatik satış makinesi olarak anılır.'),
  ('Wolfgang von Kempelen\'in 1770\'te tanıttığı ve Avrupa\'da usta oyuncuları yendiği söylenen satranç oynayan "Mekanik Türk" adlı makine hakkında doğru olan hangisidir?', 'İçinde gizlenen bir satranç ustası hamleleri yapıyordu', ['Dişli çarklarla bütün olası hamleleri hesaplıyordu', 'Buharla çalışan dişli bir hesap düzeneğiyle hamle seçiyordu', 'Delikli kartlara kaydedilmiş açılışları oynuyordu'], 'Mekanik Türk bir aldatmacaydı: kabinin içine saklanan bir oyuncu mıknatıslı taşlar yardımıyla hamleleri izleyip kolu yönetiyordu.'),
  ('1898\'de New York\'ta telsiz sinyalleriyle uzaktan yönettiği bir tekne modelini sergileyerek uzaktan kumandanın ilk gösterilerinden birini yapan mucit kimdir?', 'Nikola Tesla', ['Thomas Edison', 'Guglielmo Marconi', 'Alexander Graham Bell'], 'Tesla, Madison Square Garden\'daki elektrik sergisinde \'teleautomaton\' adını verdiği radyo denetimli tekneyi gösterdi ve buluşun patentini aldı.'),
  ('1939 New York Dünya Fuarı\'nda sesli komutlara yanıt verip yürüyebilen, Westinghouse yapımı iki metrelik insansı robotun adı nedir?', 'Elektro', ['Unimate', 'Shakey', 'Robby the Robot'], 'Westinghouse\'un Elektro adlı robotu fuarda konuşup yürüyebiliyordu; 1940\'ta yanına Sparko adlı robot köpek eklendi.'),
  ('18. yüzyıl otomatları bugünkü anlamıyla robot sayılmaz. Bunun temel nedeni nedir?', 'Çevrelerini algılayıp davranışlarını buna göre değiştiremezler', ['Metal yerine ahşaptan yapılmışlardır', 'İnsan biçiminde değildirler', 'Hareketlerini yay yerine yalnız insan gücüyle yapmaları ve kendi başlarına çalışamamaları'], 'Otomatlar önceden belirlenmiş bir hareket dizisini kör biçimde tekrarlar. Robotu ayıran algılama ve ona göre karar verme yeteneği onlarda yoktur.'),
  ('PLC\'lerin sanayide röle dolaplarının yerini almasının en önemli nedeni hangisidir?', 'Mantığın kablo sökmeden yazılımla değiştirilebilmesi', ['Elektriğe hiç gerek duymaması', 'Sensör kullanmadan çalışabilmesi', 'Röle dolaplarına göre her zaman daha yavaş ama daha sessiz çalışması'], 'Röleli sistemde her değişiklik yeniden kablolama demekti. PLC\'de aynı değişiklik program düzenlenerek yapılır, arıza bulmak da kolaylaşır.'),
  ('Bir merkezkaç regülatörü, motor hızlandığında buhar vanasını kısar. Bu davranış hangi tür geri beslemeye örnektir?', 'Negatif geri besleme', ['Pozitif geri besleme', 'İleri besleme', 'Açık çevrim zaman denetimi'], 'Çıkış (hız) arttığında düzenek onu azaltacak yönde etki eder. Sapmayı küçülten geri besleme negatif geri beslemedir ve sistemi kararlı tutar.'),
  ('Çikolata ve ilaç paketleme hatlarında saniyede birkaç ürün alıp yerleştiren, tavana asılı, üç ince kolu tek bir platformda birleşen hızlı robot türü hangisidir?', 'Delta robot', ['SCARA robot', 'Kartezyen robot', 'Silindirik robot'], 'Delta robotta motorlar sabit tabandadır, hareket eden kütle hafif kollar ve küçük platformdan ibarettir. Bu yüzden çok yüksek ivmelere ulaşabilir.'),
  ('Bütün eklemleri döner eklem olan, omuz, dirsek ve bilek benzeri yapısıyla insan koluna benzeyen ve sanayide en yaygın kullanılan robot kol türü hangisidir?', 'Mafsallı (antropomorfik) robot', ['Kartezyen portal (gantri) robot', 'Silindirik koordinatlı robot', 'Delta (paralel) robot'], 'Altı döner eklemli mafsallı kollar kaynak, boya ve montajda en çok kullanılan tiptir; geniş ve esnek bir çalışma alanı sunarlar.'),
  ('Robotlarda ileri-geri kayma (doğrusal öteleme) hareketi yapan ekleme ne ad verilir?', 'Prizmatik eklem', ['Küresel eklem', 'Kardan eklemi', 'Menteşe (döner) eklem'], 'Prizmatik eklem bir eksen boyunca doğrusal hareket sağlar; eklem değişkeni açı değil uzunluktur.'),
  ('Bir robot katalogunda "tekrarlanabilirlik ±0,02 mm" yazıyor. Bu değer neyi anlatır?', 'Robotun aynı öğretilmiş noktaya tekrar tekrar ne kadar yakın döndüğünü', ['Robotun hesaplanan herhangi bir koordinata ne kadar yakın gittiğini', 'Robotun en küçük hareket adımını', 'Robotun tam hızda taşıyabileceği yükteki en büyük sapmayı'], 'Tekrarlanabilirlik, aynı noktaya yapılan tekrar hareketlerin birbirine yakınlığıdır. Mutlak doğruluk ise hesaplanmış bir hedefe ne kadar yaklaşıldığını gösterir.'),
  ('Bir robot kolun teknik föyünde "erişim: 1400 mm" yazması neyi anlatır?', 'Bilek merkezinin tabandan uzanabileceği en büyük uzaklığı', ['Robotun saniyede alabileceği yolu', 'Robotun taşıyabileceği en ağır yükün kilogram cinsinden değerini', 'Kablosunun en fazla uzunluğunu'], 'Erişim, kolun tam açıldığında ulaşabildiği en uzak noktayı belirtir ve çalışma alanının büyüklüğünü gösterir.'),
  ('Kapalı kinematik zincirle açık kinematik zincir arasındaki fark hangisidir?', 'Kapalıda bağlar bir döngü oluşturur, açıkta tabandan uca tek bir dizi uzanır', ['Açık zincirde hiç eklem yoktur', 'Kapalı zincir yalnız hidrolikle, açık zincir yalnız elektrikle sürülür', 'Açık zincir paralel robotlarda, kapalı zincir seri kollarda görülür'], 'Seri robot kolları açık zincirdir; delta ve Stewart platformu gibi paralel robotlarda kollar uçta birleşip kapalı döngüler kurar.'),
  ('Bir robotun uç işlevcisinin yönelimini değiştirmek için bilekte genellikle kaç döner eksen bulunur?', '3', ['1', '2', '6'], 'Konum için gövde ve kolda üç eksen, yönelim için bilekte üç eksen bulunur; toplam altı eksenle her konum ve yönelim elde edilir.'),
  ('Bir fabrikada büyük cam levhaları ve düz sac panelleri yüzeyine iz bırakmadan kaldırmak için en uygun robot tutucusu hangisidir?', 'Vakumlu (vantuzlu) tutucu', ['İki parmaklı mekanik paralel tutucu', 'Kanca biçimli asma tutucu', 'İğneli tekstil tutucusu'], 'Vakum tutucular düz ve gözeneksiz yüzeylere sızdırmaz biçimde yapışır, kuvveti geniş alana yayarak çizik bırakmadan kaldırır.'),
  ('Bir hurda tesisinde elektromıknatıslı bir tutucuyla metal parçalar ayrılıyor. Aşağıdaki parçalardan hangisi bu tutucuyla kaldırılamaz?', 'Alüminyum içecek kutusu', ['Çelik cıvata', 'Dökme demir kapak', 'Çelik konserve kutusu'], 'Elektromıknatıs yalnız demir, çelik gibi ferromanyetik malzemeleri çeker; alüminyum manyetik olarak çekilmez.'),
  ('Bir robot farklı işler için kaynak torcu, vidalama ünitesi ve tutucu arasında operatör olmadan geçiş yapabiliyor. Bunu sağlayan bileğe bağlı donanıma ne ad verilir?', 'Otomatik takım değiştirici', ['Dişli kutusu', 'Bilek enkoderi', 'Kuvvet-tork sensörü'], 'Takım değiştiricinin robot tarafı ve takım tarafı vardır; mekanik kilit ile hava ve elektrik bağlantıları tek hamlede kurulup ayrılır.'),
  ('Bir gıda fabrikası domates, çilek ve hamur işi gibi biçimi düzensiz ve kolay ezilen ürünleri paketleyecek. Hangi tutucu tasarımı en uygundur?', 'Esnek malzemeden yapılmış, havayla şişen yumuşak parmaklar', ['Yüksek kuvvetli elektromıknatıs', 'Çelik çeneli, yüksek kuvvetli hidrolik mengene', 'Sivri uçlu iğneli tutucu'], 'Yumuşak tutucular nesnenin biçimine uyarak kuvveti geniş alana yayar; bu da kırılgan ve düzensiz ürünlerde hasarı önler.'),
  ('Robot hücrelerinin girişine konan ışık perdesinin görevi nedir?', 'Işınlardan biri kesildiğinde robotu durdurarak tehlikeli alana girişi algılamak', ['Hücreyi aydınlatarak kameraların parçaları daha iyi görmesini ve okumasını sağlamak', 'Robotun parçaları saymasına yardım etmek', 'Kaynak ışığının operatörün gözüne ulaşmasını engellemek'], 'Işık perdesi verici ile alıcı arasında paralel kızılötesi ışınlar oluşturur. Bir el ya da gövde ışını kestiğinde güvenlik devresi robotu durdurur.'),
  ('Bir robotun bakımına giren teknisyen, enerji kaynağını kapatıp şalterine kendi asma kilidini ve adının yazılı olduğu bir etiketi takıyor. Bu uygulamanın adı nedir?', 'Kilitle-etiketle', ['Hız ve ayrım izleme', 'Güç ve kuvvet sınırlama', 'Acil durdurma kategorisi'], 'Kilitle-etiketle uygulamasında enerjiyi yalnız kilidi takan kişi yeniden açabilir; bakım sırasında başkasının makineyi yanlışlıkla çalıştırması önlenir.'),
  ('Acil durdurma düğmelerinin genellikle sarı zemin üzerinde kırmızı ve mantar biçiminde yapılmasının temel amacı nedir?', 'Panik anında kolayca görülüp avuçla basılabilmesi', ['Düğmenin daha ucuza üretilmesi', 'Robotun düğmeyi kamerasıyla kolayca tanıyıp kendini durdurabilmesi', 'Düğmenin yanlışlıkla bırakılmasını kolaylaştırmak'], 'Standart renk ve büyük mantar biçimi, acil durumda düğmenin tereddütsüz bulunmasını ve tam bir el darbesiyle basılmasını sağlar.'),
  ('Bir sıcaklık sensörü 20,00 °C ile 20,05 °C arasındaki farkı ayırt edemiyor, ancak 0,1 °C\'lik değişimi gösterebiliyor. Bu bilgi sensörün hangi özelliğiyle ilgilidir?', 'Çözünürlük', ['Doğrusallık', 'Ölçüm aralığı', 'Tepki süresi'], 'Çözünürlük, sensörün algılayıp gösterebildiği en küçük değişimdir. Burada çözünürlük yaklaşık 0,1 °C düzeyindedir.'),
  ('LM35 sıcaklık sensörü her 1 °C için 10 mV çıkış verir ve 0 °C\'de 0 V üretir. Sensörün çıkışı 0,37 V ölçülüyorsa sıcaklık kaç °C\'dir?', '37 °C', ['3,7 °C', '370 °C', '27 °C'], '0,37 V = 370 mV; 370 mV ÷ 10 mV/°C = 37 °C.'),
  ('Bir sensör giriş birimi başına ne kadar çıkış değişimi ürettiğini anlatan özellik hangisidir? Örneğin bir mikrofonun 1 paskal ses basıncında kaç milivolt verdiği.', 'Duyarlılık (hassasiyet)', ['Histerezis', 'Ölü bölge', 'Örnekleme hızı (frekansı)'], 'Duyarlılık, çıkış değişiminin giriş değişimine oranıdır; mV/Pa ya da mV/°C gibi birimlerle verilir.'),
  ('Bir enerji türünü başka bir enerji türüne dönüştüren aygıtlara genel olarak ne ad verilir? Örneğin hoparlör elektriği sese, mikrofon sesi elektriğe çevirir.', 'Dönüştürücü', ['Modülatör', 'Kondansatör (sığaç) elemanı', 'Yükselteç'], 'Dönüştürücü (transdüser) bir fiziksel büyüklüğü başka biçimde enerjiye çevirir. Sensörler ve aktüatörler bu genel tanımın içindedir.'),
  ('Bir kuvvet sensörü yük yokken 0 N yerine sürekli 0,8 N gösteriyor; her ölçüme bu fark aynen ekleniyor. Bu hata türüne ne denir ve en kolay nasıl giderilir?', 'Sıfır kayması; yüksüz okuma çıkarılarak (dara alınarak) giderilir', ['Rastgele hata; ölçüm sayısı artırılarak giderilir', 'Histerezis; sensör ısıtılarak giderilir', 'Çözünürlük hatası; daha uzun ve daha kalın bir kablo kullanılarak giderilir'], 'Her okumaya eklenen sabit fark sıfır (ofset) hatasıdır. Yüksüzken okunan değer kaydedilip sonraki ölçümlerden çıkarılarak düzeltilir.'),
  ('Termokupllar hangi fiziksel olaya dayanarak sıcaklığı elektrik sinyaline çevirir?', 'Seebeck etkisi', ['Hall etkisi', 'Fotoelektrik etki', 'Doppler etkisi'], 'İki farklı metalin birleşim noktaları farklı sıcaklıktayken devrede küçük bir gerilim oluşur. 1821\'de Thomas Seebeck\'in bulduğu bu olay termokuplların temelidir.'),
  ('NTC türü bir termistörün sıcaklık arttıkça direnci nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce artar, sonra sıfıra iner'], 'NTC \'negatif sıcaklık katsayısı\' anlamına gelir: sıcaklık yükseldikçe yarı iletkendeki taşıyıcı sayısı artar ve direnç düşer.'),
  ('Eski ütü ve ısıtıcı termostatlarında kullanılan bimetal şerit sıcaklık değişince neden bükülür?', 'Birbirine yapıştırılan iki metalin ısıl genleşme katsayılarının farklı olması', ['Metallerden birinin ısınınca mıknatıslanıp öteki metali kendine doğru çekmesi', 'Isınan metalin elektrik yükü biriktirmesi', 'Metallerden birinin ısınınca erimesi'], 'Isınınca bir metal ötekinden daha çok uzar; bağlı oldukları için şerit, daha az genleşen metal tarafına doğru kıvrılır ve bir kontağı açıp kapatabilir.'),
  ('Bir gerinim ölçer (strain gauge) çekme kuvvetiyle birlikte uzadığında direnci neden artar?', 'İletken ince ve uzun hâle geldiği için', ['İletkenin rengi değiştiği için', 'İletkendeki elektronlar donduğu için', 'Uzayan telin manyetik alanı azaldığı için'], 'Direnç uzunlukla doğru, kesit alanıyla ters orantılıdır. Uzama hem boyu artırır hem kesiti daraltır; ikisi de direnci yükseltir.'),
  ('Elektronik tartıların, kantarların ve robot bileklerindeki kuvvet ölçümünün temelinde çoğu zaman metal bir gövdeye yapıştırılmış gerinim ölçerler bulunur. Bu tür sensöre ne ad verilir?', 'Yük hücresi', ['Döner enkoder', 'Hall sensörü', 'Fotokapı'], 'Yük hücresinde kuvvet metal gövdeyi çok az esnetir, üzerindeki gerinim ölçerler bu esnemeyi direnç değişimine çevirir.'),
  ('Bir robotun bileğine takılan altı eksenli kuvvet-tork sensörü hangi büyüklükleri ölçer?', 'Üç eksende kuvvet ve üç eksen çevresinde moment', ['Altı farklı noktadaki sıcaklık', 'Altı eklemin açısal konumu', 'Üç eksende doğrusal hız ve üç eksende doğrusal ivme'], 'Bu sensör uç işlevciye etkiyen Fx, Fy, Fz kuvvetleri ile Mx, My, Mz momentlerini ölçer; parlatma, montaj ve el ile kılavuzlamada kullanılır.'),
  ('Bir konveyörde ilerleyen çelik vidaları dokunmadan sayan, osilatör bobininin oluşturduğu alanda metalin girdap akımlarıyla yarattığı değişimi algılayan sensör hangisidir?', 'Endüktif yakınlık sensörü', ['Kapasitif nem sensörü', 'Pasif kızılötesi hareket sensörü', 'Ultrasonik seviye sensörü'], 'Endüktif sensörün bobini değişken bir manyetik alan üretir; yaklaşan metalde oluşan girdap akımları osilatörü zayıflatır ve çıkış değişir.'),
  ('Fotoelektrik sensörlerde verici ile alıcının karşılıklı iki ayrı gövdede bulunduğu ve nesnenin ışını kesmesiyle algılama yapılan düzenlemenin başlıca üstünlüğü nedir?', 'En uzun algılama mesafesini ve en güvenilir algılamayı sunması', ['Tek bir gövdeyle kurulabilmesi ve kablo gerektirmemesi', 'Yalnız şeffaf ve renksiz nesneleri algılayabilmesi', 'Nesnelerin rengini ayırt edebilen tek düzenleme olması'], 'Karşılıklı (ışın kesme) düzenlemede ışın doğrudan alıcıya gider; nesnenin yansıtıcılığından etkilenmediği için menzil uzun ve algılama kararlıdır.'),
  ('Cam bir tüp içindeki iki ince ferromanyetik dilin, yakına bir mıknatıs gelince birbirine değerek devreyi kapattığı anahtar hangisidir?', 'Reed anahtar', ['Limit (sınır) anahtarı', 'Termostatik anahtar', 'Civa eğim anahtarı'], 'Mıknatısın alanı dilleri mıknatıslar ve birbirine çeker. Kapı-pencere alarmlarında ve pnömatik silindirlerde piston konumunu algılamada kullanılır.'),
  ('Bir hobi servo motorunun içinde, çıkış milinin açısını ölçüp devreye geri bildiren genellikle hangi eleman bulunur?', 'Potansiyometre', ['Termistör', 'Gerinim ölçer köprüsü', 'Fotodiyot'], 'Çıkış miline bağlı potansiyometre açıya göre gerilim üretir; servo devresi bu gerilimi komut sinyaliyle karşılaştırıp motoru hedef açıya sürer.'),
  ('Uçları 0 V ve 5 V\'a bağlı, 270 derece dönebilen doğrusal bir potansiyometrenin orta ucunda 2,5 V ölçülüyor. Mil, başlangıç konumundan kaç derece dönmüştür?', '135°', ['90°', '180°', '125,5°'], 'Gerilim açıyla doğru orantılı: 2,5 / 5 = 0,5; 0,5 × 270° = 135°.'),
  ('Artımlı (inkremental) enkoder kullanan bir robot, elektrik kesintisinden sonra açıldığında neden önce bir "referans arama" (homing) hareketi yapmak zorundadır?', 'Artımlı enkoder yalnız hareket miktarını sayar, güç kesilince mutlak konum bilgisi kaybolur', ['Enkoder elektrik kesilince kalıcı olarak bozulur', 'Motorların ısınması için önce boşta dönmesi gerekir', 'Referans arama yalnız robotun boya işlerinde kullanılan özel bir ayar olduğundan her açılışta yapılır'], 'Artımlı enkoder darbeleri sayar; sayaç sıfırlanınca robot nerede olduğunu bilemez ve bilinen bir referans noktasına gidip sayımı oradan başlatır.'),
  ('Fırçasız DC motorlarda sargılara akımın doğru sırayla verilebilmesi için rotorun konumu çoğu zaman stator içine yerleştirilen hangi sensörlerle algılanır?', 'Hall etkisi sensörleri', ['Termokupllar', 'Gerinim ölçerler', 'Nem sensörleri'], 'Rotordaki mıknatısların konumunu üç Hall sensörü algılar; sürücü bu bilgiye göre hangi sargının enerjilendirileceğine karar verir.'),
  ('Bir masa üzerinde hareketsiz duran üç eksenli ivmeölçerin düşey (z) ekseni neden sıfır değil yaklaşık 1 g gösterir?', 'Duran sensör, masanın yukarı itişini ivme gibi algılar', ['Dünya\'nın kendi ekseni etrafındaki dönüşü sensörü sürekli ivmelendirir', 'Sensörün içindeki pil her zaman 1 g\'lik bir sapma üretecek biçimde ayarlanır', 'Masanın titreşimleri ortalamada tam 1 g\'lik bir değer oluşturur'], 'İvmeölçer, içindeki küçük kütleye etkiyen yerçekimi dışındaki kuvvetleri ölçer. Duran sensörde masanın yukarı itişi 1 g\'lik ivme gibi görünür; bu yüzden eğim ölçümünde de kullanılır.'),
  ('Üç eksenli bir ivmeölçer serbest düşen bir telefonun içinde ne okur?', 'Her üç eksende de sıfıra yakın değer', ['Düşey eksende 2 g', 'Düşey eksende 1 g, yatay eksenlerde 1 g', 'Düşey eksende −9,8 g'], 'Serbest düşüşte sensörün kütlesi ve gövdesi aynı ivmeyle düşer; aralarında kuvvet oluşmaz. Bazı dizüstü bilgisayarlar bu sıfır okumayla düşmeyi algılayıp disk kafasını park eder.'),
  ('Bir ataletsel ölçüm biriminin (IMU) teknik özelliklerinde "9 eksen" yazıyor. Bu hangi sensörlerin bir arada olduğunu gösterir?', 'Üç eksenli ivmeölçer, üç eksenli jiroskop ve üç eksenli manyetometre', ['Dokuz ayrı sıcaklık sensörü', 'Üç eksenli ivmeölçer, üç barometre ve üç ayrı GPS alıcısı', 'Üç kamera, üç mikrofon ve üç hoparlör'], 'Dokuz eksenli IMU\'lar üç ayrı üç eksenli sensörü birleştirir; manyetometre, yalpa açısındaki kaymayı düzeltmek için yön bilgisi sağlar.'),
  ('Hızla dönen bir rotorlu mekanik jiroskobun, dayandığı çerçeve döndürülse bile ekseninin uzaydaki yönünü korumaya çalışmasının nedeni nedir?', 'Açısal momentumun korunması', ['Sürtünmenin rotoru sabit tutması', 'Rotorun manyetik kuzeye yönelmesi', 'Havanın rotoru itmesi'], 'Dış tork olmadıkça dönen cismin açısal momentum vektörü yön değiştirmez. Eski uçak ve gemi yön göstergeleri bu ilkeye dayanır.'),
  ('Ultrasonik bir mesafe sensörü kalın bir perdeye ya da kanepeye bakarken güvenilir okuma vermiyor. Bunun en olası nedeni hangisidir?', 'Yumuşak yüzeylerin sesi soğurup zayıf yankı döndürmesi', ['Kumaşın ışığı yansıtmaması', 'Perdenin manyetik alanı bozması', 'Kanepenin sıcaklığının sensörü yanıltması'], 'Ultrasonik sensör yankıya dayanır. Kumaş ve köpük gibi yumuşak malzemeler ses enerjisinin çoğunu emer; geri dönen yankı algılanamayacak kadar zayıf kalabilir.'),
  ('Yerdeki engelleri algılamak için robot süpürgelerin önüne ve altına yerleştirilen, merdiven boşluğuna düşmeyi önleyen kızılötesi sensörler hangi adla anılır?', 'Uçurum (cliff) sensörleri', ['Tampon (bumper) sensörleri', 'Duvar takip sensörleri', 'Kir algılama sensörleri'], 'Uçurum sensörleri zemine kızılötesi ışık gönderir; yansıma birden kaybolursa önde bir boşluk olduğu anlaşılır ve robot geri döner.'),
  ('Bir kalite kontrol kamerası 8 bitlik gri görüntüde parlaklığı 128\'in üzerindeki pikselleri beyaz, diğerlerini siyah yapıyor. Bu işleme ne ad verilir?', 'İkili eşikleme', ['Kenar yumuşatma', 'Renk dengeleme', 'Görüntü sıkıştırma'], 'Eşikleme, her pikseli bir sınır değerle karşılaştırıp iki sınıftan birine atar; parçayı arka plandan ayırmanın en basit yoludur.'),
  ('Makine görüşünde parçanın kameranın karşı tarafından, arkasından aydınlatılması (arka ışık) özellikle hangi tür denetim için uygundur?', 'Dış hatları ve delikleri keskin siluetle ölçmek', ['Parçanın yüzeyindeki renk tonlarını ayırt etmek', 'Parçanın üzerindeki yazıları okumak', 'Parçanın sıcaklığını uzaktan ölçmek'], 'Arkadan aydınlatmada parça kara bir gölge, arka plan parlak görünür. Kenarlar çok net çıktığı için boyut ve delik ölçümü kolaylaşır; yüzey ayrıntısı ise kaybolur.'),
  ('Kamera kalibrasyonunda sıklıkla satranç tahtası desenli bir levhanın farklı açılardan fotoğrafları çekilir. Bu işlemin amacı nedir?', 'Mercek bozulmasını ve iç parametreleri hesaplamak', ['Kameranın renk duyarlılığını artırmak', 'Kameranın pil ömrünü ölçmek', 'Satranç oynayan robotlara oyun öğretmek'], 'Köşe noktalarının gerçek konumları bilindiği için, görüntüdeki konumlarla karşılaştırılarak odak uzaklığı, merkez noktası ve fıçı bozulması gibi parametreler kestirilir.'),
  ('Bir robot hücresinde kameranın gördüğü görüntüye göre robotun hareketinin sürekli düzeltildiği, kameranın geri besleme sensörü gibi kullanıldığı denetim yöntemine ne ad verilir?', 'Görsel servo denetim', ['Açık çevrim zamanlama', 'Merdiven mantığı', 'Elle öğretme'], 'Görsel servoda hedef ile mevcut durum arasındaki fark görüntüden ölçülür ve robot bu farkı sıfırlayacak biçimde sürülür.'),
  ('Laboratuvarlarda mobil robotların ve kameraların konumunu kolayca bulmak için ortama yapıştırılan, siyah-beyaz karelerden oluşan ve her biri benzersiz bir kimlik taşıyan desenlere ne ad verilir?', 'Referans işaretçileri', ['Kalibrasyonsuz renk lekeleri', 'Manyetik zemin bantları', 'Kızılötesi uzaktan kumanda kodlarıyla yanıp sönen LED dizileri'], 'Bu işaretçiler kamerada kolayca algılanır; köşelerinin konumundan işaretçiye göre kameranın uzaklığı ve yönelimi hesaplanabilir.'),
  ('Bir makine görüşü sisteminde, kenar algılama yöntemleri görüntünün hangi özelliğini arar?', 'Parlaklığın kısa mesafede hızla değiştiği yerleri', ['Görüntünün en parlak tek pikselini', 'Görüntüdeki toplam piksel sayısını', 'Rengi tam olarak gri olan bölgeleri'], 'Kenarlar, parlaklığın kısa mesafede belirgin biçimde değiştiği yerlerdir. Bu değişim görüntünün türevine (gradyanına) benzeyen filtrelerle bulunur.'),
  ('Bir sokak lambasının hava kararınca kendiliğinden yanmasını sağlamak için kullanılan, ışık arttıkça direnci azalan ucuz sensör hangisidir?', 'Fotodirenç (LDR)', ['Termistör', 'Gerinim ölçer (strain gauge)', 'Reed anahtar'], 'LDR (ışığa bağımlı direnç), genellikle kadmiyum sülfür içerir; karanlıkta direnci çok yüksek, aydınlıkta düşüktür.'),
  ('Sıradan bir renk sensörü bir nesnenin rengini nasıl belirler?', 'Renk filtreli fotodiyotlara düşen ışığı karşılaştırarak', ['Nesnenin sıcaklığını ölçüp renge çevirerek', 'Nesneye ses dalgası gönderip yankısını dinleyerek', 'Nesnenin ağırlığını tartıp tablodan renk seçerek'], 'Renk sensörü her biri farklı filtre taşıyan fotodiyot gruplarından oluşur; üç kanaldaki oranlar rengi belirler. Ölçüm genellikle beyaz bir LED ışığı altında yapılır.'),
  ('Evlerde kullanılan optik duman dedektörleri dumanı nasıl algılar?', 'Taneciklerin, odacıktaki ışığı algılayıcıya saçmasıyla', ['Dumanın odanın sıcaklığını bir anda 100 °C\'ye çıkarmasıyla', 'Dumanın içindeki karbonun mıknatısı çekmesiyle', 'Dumanın sesi daha hızlı iletmesiyle'], 'Odacıktaki LED ile fotodiyot birbirini doğrudan görmez. İçeri duman girince ışık taneciklere çarpıp saçılır ve fotodiyota ulaşır.'),
  ('Bir mikrodenetleyiciye yalnız iki hatla (veri ve saat) onlarca sensörün bağlanmasını, her sensörün kendine özgü adresiyle seçilmesini sağlayan seri haberleşme yolu hangisidir?', 'I²C', ['UART', 'Paralel port', 'RS-232'], 'I²C\'de bütün aygıtlar SDA (veri) ve SCL (saat) hatlarını paylaşır; ana birim her iletişimin başında aygıtın adresini gönderir.'),
  ('UART haberleşmesinde ayrı bir saat hattı yoktur. İki tarafın veriyi doğru okuyabilmesi için neyin önceden aynı ayarlanması gerekir?', 'Baud hızı', ['Aygıt adresi', 'Kablo rengi', 'Besleme akımı'], 'Asenkron haberleşmede alıcı, bitlerin süresini kendi saatine göre ölçer. Her iki taraf aynı baud hızına (örneğin 9600) ayarlanmazsa bitler kayar ve veri bozulur.'),
  ('Bir mikrodenetleyici pinine yalnız bir düğme bağlanmış, düğmenin öbür ucu toprağa gidiyor. Düğmeye basılmadığında pin rastgele 0 ve 1 okuyor. Sorunun çözümü nedir?', 'Pini bir dirençle besleme gerilimine çekmek', ['Düğmeye seri bir LED eklemek', 'Pini okuma sıklığını artırıp yüksek frekansta örneklemek', 'Düğmeyi iki kez bağlamak'], 'Basılmamış düğmede pin hiçbir yere bağlı değildir (\'havada\' kalır) ve gürültü toplar. Çekme direnci pini tanımlı bir 1 seviyesinde tutar; basılınca pin 0\'a iner.'),
  ('Bir robottaki mekanik düğmeye bir kez basıldığında sayaç bazen 3–4 birden artıyor. Bu sorunun nedeni ve yaygın çözümü hangisidir?', 'Kontak sekmesi; kısa bir bekleme ya da filtre eklemek', ['Pilin zayıflaması; pili değiştirmek', 'Mikrodenetleyicinin çok yavaş olması; daha hızlı işlemci kullanmak', 'Düğmenin manyetik alan üretmesi; düğmeyi uzaklaştırmak'], 'Metal kontaklar kapanırken birkaç milisaniye boyunca sıçrar ve birçok darbe üretir. Yazılımda kısa bir süre beklemek ya da RC filtre kullanmak bu sorunu giderir.'),
  ('Fabrikalarda sensör bilgisinin uzun kablolarla 0–10 V gerilim yerine 4–20 mA akım olarak taşınmasının başlıca nedeni nedir?', 'Akım, kablo direncinden ve gürültüden az etkilenir', ['Akımla taşınan sinyal kabloda hiç enerji harcamaz', '4–20 mA kablosuz iletime olanak verir', 'Akım sinyali sensörün sıcaklığını da taşır'], 'Akım döngüsünde seri bağlı her noktadan aynı akım geçer; kablo direnci gerilim düşümü yapsa da akım değişmez. Ayrıca düşük empedanslı döngü gürültüye daha dayanıklıdır.'),
  ('Fırçalı bir DC motorda rotor döndükçe sargılardaki akımın yönünü uygun anlarda tersine çeviren parça hangisidir?', 'Komütatör', ['Rotor mıknatısı', 'Rulman yatağı', 'Soğutma fanı ve hava kanalları'], 'Komütatör, mil üzerindeki bölümlü bir halkadır; fırçalarla temas ederek her yarım turda sargı akımını çevirir ve tork hep aynı yönde kalır.'),
  ('Fabrikalarda konveyör ve pompa motorlarının hızını ayarlamak için kullanılan "frekans dönüştürücü" (invertör) bu işi nasıl yapar?', 'Motora giden gerilimin frekansını değiştirerek', ['Motorun kutup sayısını elle değiştirerek', 'Motor miline sürtünme freni uygulayarak', 'Motorun önüne ayarlı büyük bir güç direnci bağlayarak'], 'Asenkron motorun hızı besleme frekansına bağlıdır. İnvertör şebeke gerilimini doğrultup istenen frekansta yeniden üretir; böylece hız verimli biçimde ayarlanır.'),
  ('Bir dişli kutusunda yön değiştirildiğinde çıkış mili, giriş mili bir miktar döndükten sonra harekete başlıyor. Dişliler arasındaki bu ölü harekete ne ad verilir?', 'Boşluk', ['Kayma (patinaj) kaybı', 'Rezonans', 'Doyma'], 'Dişlerin arasındaki küçük açıklık yüzünden yön değişiminde dişler önce boşluğu kapatır. Bu durum hassas robotlarda konum hatasına yol açar.'),
  ('Sonsuz vida-karşılık dişli düzeneğinin bazı vinçlerde ve kapı mekanizmalarında tercih edilmesinin önemli bir nedeni nedir?', 'Çıkış tarafındaki yükün vidayı geriye döndürememesi', ['Çok yüksek verimle enerji kaybını sıfırlaması', 'Giriş ve çıkış millerinin aynı eksende olması', 'Her iki yönde de serbestçe geri sürülebilmesi'], 'Birçok sonsuz vida düzeneği kendinden kilitlidir: yük çıkış dişlisini döndürmeye çalışsa da vida dönmez. Böylece motor durduğunda yük yerinde kalır.'),
  ('Bilyalı vidalı millerin sıradan trapez vidalı millere göre makinelerde tercih edilmesinin başlıca nedeni nedir?', 'Yuvarlanan bilyalar sayesinde sürtünmenin azalması', ['Bilyaların vidayı kendinden kilitli hâle getirmesi', 'Bilyalı vidaların hiç yağlama gerektirmemesi', 'Bilyalı vidaların yalnız dönme hareketi üretmesi'], 'Somun ile mil arasında dolaşan bilyalar kayma yerine yuvarlanma sürtünmesi sağlar; verim yüksek, ısınma ve aşınma düşük olur.'),
  ('Ortada bir güneş dişlisi, çevresinde ona ve dıştaki halka dişliye kavrayan birkaç uydu dişlisi bulunan dişli düzeneğine ne ad verilir?', 'Planet (gezegen) dişli', ['Kremayer-pinyon düzeneği', 'Kayış-kasnak', 'Konik dişli'], 'Yük birkaç uydu dişlisine paylaştırıldığı için planet dişli küçük hacimde yüksek tork ve oran sağlar; motor redüktörlerinde yaygındır.'),
  ('3D yazıcılarda baskı kafasını taşımak için düz kayış yerine dişli (triger) kayış kullanılmasının nedeni nedir?', 'Kayışın kasnakta kaymadan konumu korumasını sağlamak', ['Kayışın daha ucuz olması', 'Kayışın elektrik iletmesi', 'Kayışın sesi artırarak arızayı haber vermesi'], 'Dişli kayış kasnağın dişlerine oturur; düz kayışlardaki kayma olmadığından motorun attığı adımlar kafanın konumuna eksiksiz aktarılır.'),
  ('Bir DC motorun dönüş yönünü mikrodenetleyiciyle değiştirebilmek için dört anahtardan oluşan hangi devre kullanılır?', 'H köprüsü', ['Gerilim bölücü', 'Tam dalga doğrultucu', 'Osilatör devresi'], 'H köprüsünde çapraz anahtar çiftleri kapatılarak motor uçlarına iki yönde gerilim uygulanabilir; bu da dönüş yönünü değiştirir.'),
  ('12 V\'luk bir kaynaktan PWM ile sürülen bir DC motorda görev oranı %25\'tir. Motorun gördüğü ortalama gerilim yaklaşık kaç volttur?', '3 V', ['4 V', '6 V', '9 V'], 'Ortalama gerilim = görev oranı × kaynak gerilimi = 0,25 × 12 = 3 V. Anahtarlama hızlı olduğundan motor bunu ortalama bir gerilim gibi algılar.'),
  ('Hidrolik bir krikoda küçük pistonun alanı 10 cm², büyük pistonun alanı 500 cm²\'dir. Küçük pistona 100 N kuvvet uygulanırsa büyük piston en çok kaç N\'luk yük kaldırabilir? (Kayıplar ihmal)', '5000 N', ['500 N', '50.000 N', '1000 N'], 'Pascal ilkesine göre basınç her yere eşit iletilir: F₂ = F₁ × A₂ ÷ A₁ = 100 × 500 ÷ 10 = 5000 N.'),
  ('Tek etkili bir pnömatik silindiri çift etkili olandan ayıran özellik hangisidir?', 'Hava yalnız bir yönde iter, geri dönüşü bir yay sağlar', ['Silindir yalnız hidrolik yağla çalışabilir, havayla çalışmaz', 'Pistonu her iki yönde de basınçlı hava sürer ve iki ayrı hava girişi bulunur', 'Silindirin içinde hiç piston bulunmaz, gövdenin kendisi uzar'], 'Tek etkili silindirde tek hava girişi vardır; hava kesilince içteki yay pistonu geri iter. Çift etkilide iki yöne de havayla güç uygulanır.'),
  ('Pnömatik devre şemalarında "5/2 valf" ifadesindeki sayılar neyi anlatır?', '5 bağlantı ağzı ve 2 anahtarlama konumu', ['5 bar çalışma basıncı ve 2 saniye tepki süresi', '5 mm boru çapı ve 2 adet silindir', '5 W bobin gücü ve 2 adet yay'], 'İlk sayı valfteki bağlantı ağzı (port), ikincisi konum sayısıdır. 5/2 valfler çift etkili silindirleri iki yönde sürmek için yaygındır.'),
  ('Bir fabrikanın basınçlı hava hattında makinelerin hemen önüne konan "şartlandırıcı" (FRL) ünitesi hangi üç işi görür?', 'Havayı süzer, basıncını ayarlar ve gerekirse yağlar', ['Havayı ısıtır, soğutur ve yeniden ısıtır', 'Havayı sıkıştırır, depolar ve dışarı atar', 'Havanın debisini, sıcaklığını ve nem oranını ölçüp kaydeder'], 'Filtre su ve tozu tutar, regülatör çalışma basıncını sabitler, yağlayıcı da gereken sistemlerde havaya ince yağ zerrecikleri katar.'),
  ('Bir pnömatik silindirin hareket hızını ayarlamanın en yaygın yolu hangisidir?', 'Silindir hattına ayarlı akış kısma valfi koymak', ['Kompresörün elektrik kablosunu kısaltmak', 'Silindirin rengini değiştirmek', 'Silindirin içine daha ağır bir piston yerleştirmek'], 'Silindirin hızı içine giren ya da dışarı çıkan hava debisine bağlıdır. Akış kısma valfi debiyi sınırlayarak hızı ayarlar; genellikle çıkan hava kısılır.'),
  ('Bir hidrolik devrede akışkanın yalnız tek yönde geçmesine izin verip geri akışı engelleyen valf hangisidir?', 'Çek valf', ['Basınç düşürme valfi', 'Oransal yön valfi', 'Emniyet valfi'], 'Çek valfte bir bilye ya da klape bir yönde akışla açılır, ters yönde akış onu yuvasına bastırıp kapatır.'),
  ('Eski tip bir çamaşır makinesi yalnız önceden ayarlanmış sürelere göre su alıp yıkıyor; çamaşırın gerçekten temizlenip temizlenmediğini ölçmüyor. Bu sistem hangi denetim türüne örnektir?', 'Açık çevrim denetim', ['Kapalı çevrim denetim', 'Uyarlamalı denetim', 'Kaskad denetim'], 'Açık çevrim sistem çıkışı ölçüp girişe geri bildirmez; zamanlayıcıyla belirlenen adımları sonuca bakmadan uygular.'),
  ('Bir robot eklemine 100°\'ye gitme komutu veriliyor. Eklem önce 115°\'ye kadar çıkıp sonra salınarak 100°\'de duruyor. Aşma yüzde kaçtır?', '%15', ['%115', '%1,5', '%30'], 'Aşma = (tepe değer − son değer) ÷ son değer × 100 = (115 − 100) ÷ 100 × 100 = %15.'),
  ('Mikrofon hoparlöre yaklaştırıldığında oluşan yüksek ıslık sesi (Larsen etkisi) hangi tür geri beslemenin sonucudur?', 'Pozitif geri besleme', ['Negatif geri besleme', 'İleri besleme', 'Açık çevrim denetim'], 'Hoparlörden çıkan ses mikrofona girip yeniden yükseltilir; sinyal her turda büyüdüğü için sistem kararsızlaşır ve çınlama oluşur.'),
  ('Basit bir aç-kapa (bang-bang) denetleyici ile oransal denetleyici arasındaki temel fark hangisidir?', 'Aç-kapa tam açık ya da kapalıdır; oransal çıkış hatayla değişir', ['Aç-kapa sensör kullanmaz; oransal denetleyici ise hiç geri bildirime gerek duymaz', 'Aç-kapa yalnız hidrolikte, oransal yalnız elektrik motorlarında kullanılır', 'Aç-kapa denetleyici her zaman daha hassas ve salınımsızdır'], 'Aç-kapa denetimde aktüatör ya tam güçte ya kapalıdır, çıkış hedef çevresinde dalgalanır. Oransal denetimde düzeltme hatayla birlikte küçülür.'),
  ('Bir PLC\'nin programını çalıştırırken sürekli tekrarladığı tarama döngüsünün doğru sırası hangisidir?', 'Girişleri oku, programı işle, çıkışları güncelle', ['Çıkışları güncelle, girişleri oku, programı sil', 'Programı derle, girişleri kapat, çıkışları sıfırla', 'Programı işle, ağa bağlan, girişleri en sona bırak'], 'PLC her taramada önce tüm girişlerin anlık görüntüsünü alır, programı bu görüntüye göre işler ve sonuçları çıkışlara toplu olarak yazar.'),
  ('PLC programlamada en yaygın dillerden olan merdiven diyagramının (ladder) sanayide tutulmasının başlıca nedeni nedir?', 'Röle şemalarına benzediği için kolayca okunabilmesi', ['Yalnızca nesne yönelimli programlamayı desteklemesi', 'Programın her zaman en hızlı bu dilde çalışması', 'Merdiven diyagramının yalnızca grafik kartlarında çalışabilmesi'], 'Merdiven diyagramı, iki dikey güç hattı arasında kontak ve bobinlerden oluşan basamaklarla yazılır; röle dolaplarıyla çalışmış teknisyenler mantığı hemen tanır.'),
  ('Merdiven diyagramında iki kontağın aynı basamakta art arda (seri) yerleştirilmesi hangi mantık işlemine karşılık gelir?', 'VE', ['VEYA', 'DEĞİL', 'ÖZEL VEYA'], 'Akımın bobine ulaşması için seri kontakların hepsi kapalı olmalıdır; bu VE işlemidir. Paralel kontaklar ise VEYA işlemini kurar.'),
  ('Bir dolum hattında her 12 şişe geçtiğinde bir kolinin kapatılması isteniyor. PLC\'de en uygun komut hangisidir?', 'Ön ayarı 12 olan yukarı sayıcı', ['Ön ayarı 12 saniye olan zamanlayıcı', '12 bitlik analog giriş modülü', '12 basamaklı mühürleme devresi'], 'Sayıcı sensörden gelen her darbede bir artar; ön ayar değerine ulaşınca çıkışını etkinleştirir ve kolileme başlatılıp sayıcı sıfırlanır.'),
  ('Fabrikalarda yüzlerce sensörün her biri için PLC\'ye ayrı kablo çekmek yerine "saha veri yolu" kullanılmasının başlıca yararı nedir?', 'Çok sayıda aygıtın tek ortak kablodan haberleşmesi', ['Sensörlerin hiç elektrik enerjisi gerektirmemesi', 'Kablonun her sensöre ayrı ayrı çekilmesini zorunlu kılması', 'Haberleşmenin yalnız gece saatlerinde yapılabilmesi'], 'Saha veri yolları kablolamayı ve montaj maliyetini büyük ölçüde azaltır; ayrıca aygıtlardan tanı bilgisi de alınabilir.'),
  ('Bir fabrikada motor rulmanlarının titreşimi sensörlerle sürekli izleniyor ve titreşim belirli bir örüntüye girince, arıza oluşmadan bakım planlanıyor. Bu yaklaşıma ne ad verilir?', 'Kestirimci bakım', ['Arızadan sonra onarım', 'Takvime bağlı periyodik bakım', 'Bakımsız çalıştırma ve parça değiştirme'], 'Kestirimci bakımda parçanın gerçek durumu ölçülür; bakım ne çok erken (gereksiz) ne de arızadan sonra (pahalı) yapılır.'),
  ('Akıllı fabrikalarda müşterinin her siparişi farklı renk ve seçeneklerle tek tek üretilirken seri üretimin düşük maliyetine yaklaşılması hedefine ne ad verilir?', 'Kitlesel kişiselleştirme', ['Tek tip seri üretim', 'El işçiliğiyle zanaat üretimi', 'Stoka yönelik toplu üretim'], 'Esnek robot hücreleri, ürünün kendi kimliğini taşıyan etiketleri ve yazılımla yönetilen hatlar, her ürünün farklı olmasına rağmen üretimin otomatik sürmesini sağlar.'),
  ('Bir elektrik panosunda gevşek bağlantıları arıza çıkmadan bulmak için bakım ekibinin en uygun aracı hangisidir?', 'Termal (kızılötesi) kamera ile sıcak noktaları aramak', ['Panoyu kapatıp içini uzun süre kulakla dinleyerek ses aramak', 'Panonun ağırlığını tartmak', 'Pano kapağının rengini incelemek'], 'Gevşek bağlantıların direnci artar ve bu noktalar çevreye göre ısınır; termal kamera bu sıcak noktaları temassız ve çalışma sırasında gösterir.'),
  ('Dört tekerlekli, statik olarak dengeli bir robot ile iki ayaklı yürüyen bir robot karşılaştırılıyor. Bacaklı robotların tipik üstünlüğü hangisidir?', 'Merdiven ve engebeli araziyi aşabilmeleri', ['Düz zeminde çok daha az enerji harcamaları', 'Daha basit denetim gerektirmeleri', 'Daha ucuz üretilmeleri'], 'Bacaklar tek tek basma noktaları seçebildiği için basamak, taş ve çukurları aşabilir. Karşılığında denetimleri karmaşıktır ve düz zeminde tekerlekten daha verimsizdirler.'),
  ('Bir robotun haritasında odalar düğüm, kapılar ve koridorlar bu düğümleri bağlayan kenarlar olarak tutuluyor; metre cinsinden ayrıntılı geometri yok. Bu harita türü hangisidir?', 'Topolojik harita', ['Doluluk ızgara haritası', 'Nokta bulutu haritası', 'Yükseklik haritası'], 'Topolojik harita \'hangi yer hangisine bağlı\' bilgisini tutar; az bellekle büyük alanlarda üst düzey rota planlamaya uygundur.'),
  ('Dört yöne (yukarı, aşağı, sağ, sol) hareket edebilen bir ızgara robotu (2, 3) hücresinden (7, 9) hücresine engelsiz bir alanda en az kaç adımda ulaşır?', '11', ['6', '5', '13'], 'Çapraz hareket olmadığı için uzaklık Manhattan uzaklığıdır: |7 − 2| + |9 − 3| = 5 + 6 = 11.'),
  ('Bir çim biçme ya da tarla püskürtme robotunun alanın her noktasından en az bir kez geçecek biçimde gidip gelme (öküz sürme) desenini planlamasına ne ad verilir?', 'Kapsama yol planlaması', ['En kısa yol planlaması', 'Ters kinematik', 'Döngü kapatma'], 'Kapsama planlamasında amaç bir noktaya ulaşmak değil, alanın tamamını taramaktır; şeritler halinde gidip gelme bu işin klasik desenidir.'),
  ('Drone\'larda her fırçasız motorun yanında bulunan ve uçuş denetleyicisinden gelen komuta göre motora uygun sırayla akım veren devreye ne ad verilir?', 'Elektronik hız denetleyicisi', ['Gerilim bölücü', 'Analog-sayısal dönüştürücü (ADC) kartı', 'Anten yükselteci'], 'ESC, bataryanın doğru akımını fırçasız motorun üç fazına sırayla anahtarlayarak motorun hızını ayarlar.'),
  ('Bir drone\'un uçuş denetleyicisi motor hızlarını saniyede yüzlerce kez yeniden hesaplar. Bunun başlıca nedeni nedir?', 'Çok rotorlu araçlar doğası gereği kararsızdır', ['Pervaneler her saniye yön değiştirmek zorundadır', 'Pil gerilimi saniyede yüzlerce kez sıfırlanır', 'Kumanda yalnız bu hızda sinyal gönderebilir'], 'Dört rotorlu bir araçta küçük bir dengesizlik hızla büyür. Denetleyici IMU verisine göre çok hızlı düzeltmeler yaparak aracı dengede tutar.'),
  ('Bir drone\'un yazılımına havalimanı çevresi gibi bölgelerin koordinatları girilir ve araç bu bölgelere girmeyi reddeder. Bu özelliğe ne ad verilir?', 'Coğrafi sınırlama (geofencing)', ['Optik akış', 'Kendi ekseni çevresinde dönme (yaw)', 'Otomatik kalkış'], 'Coğrafi sınırlama, GPS konumunu yasak bölge sınırlarıyla karşılaştırarak aracı uzak tutar; güvenlik ve mevzuata uyum için kullanılır.'),
  ('Gösterilerde yüzlerce ışıklı drone\'un gökyüzünde şekiller oluşturması, robotikte hangi alanın uygulamasıdır?', 'Çok robotlu (sürü) koordinasyon', ['Tek eklemli robot kol denetimi', 'Endüstriyel kaynak otomasyonu', 'Sualtı robotiği'], 'Her drone\'a zamanla değişen bir konum atanır ve hepsinin çarpışmadan eşzamanlı hareket etmesi sağlanır; bu, çoklu robot planlamasının gösterişli bir örneğidir.'),
  ('Sualtı robotlarının yüzeydeki gemiyle iletişimde radyo yerine çoğunlukla ses dalgalarını (akustik modem) kullanmasının nedeni nedir?', 'Radyo dalgalarının tuzlu suda çok hızlı sönümlenmesi', ['Ses dalgalarının suda ışıktan daha hızlı ilerlemesi', 'Radyo vericilerinin suda patlama tehlikesi taşıması', 'Balıkların radyo dalgalarını engellemesi'], 'Elektromanyetik dalgalar iletken deniz suyunda birkaç metrede zayıflar. Ses ise suda kilometrelerce yol alabilir; karşılığında veri hızı düşüktür.'),
  ('Ameliyatlarda kullanılan da Vinci cerrahi sistemi hakkında hangi ifade doğrudur?', 'Cerrahın konsoldan yönettiği, ameliyatı kendi başına yapmayan bir sistemdir', ['Ameliyatı cerrah olmadan baştan sona kendisi yapan otonom bir robottur', 'Yalnız diş çekiminde kullanılan küçük bir el aletidir', 'Hastanın ilaçlarını dağıtan bir hastane lojistik robotudur'], 'da Vinci\'de cerrah hasta başındaki robot kollarını üç boyutlu görüntü veren bir konsoldan yönetir; robot cerrahın hareketlerini ölçekler ve titremesini süzer.'),
  ('Robotik cerrahide "hareket ölçekleme" 5:1 olarak ayarlanmışsa cerrah elini 10 mm hareket ettirdiğinde alet ucu ne kadar hareket eder?', '2 mm', ['5 mm', '50 mm', '10 mm'], '5:1 ölçeklemede alet hareketi el hareketinin beşte biridir: 10 ÷ 5 = 2 mm. Bu, çok küçük dokularda hassasiyeti artırır.'),
  ('İnme geçiren bir hastanın koşu bandı üzerinde, bacaklarına bağlı motorlu bir düzenekle tekrar tekrar doğru yürüme hareketini yapmasını sağlayan sistemler hangi gruba girer?', 'Rehabilitasyon robotları', ['Cerrahi robotlar', 'Endüstriyel kaynak robotları', 'Sualtı robotları'], 'Rehabilitasyon robotları hastaya çok sayıda düzgün tekrar yaptırarak sinir sisteminin yeniden öğrenmesini destekler; terapistin fiziksel yükünü de azaltır.'),
  ('Bazı hastanelerde boş odalarda dolaşıp yüzeyleri güçlü morötesi (UV-C) ışıkla tarayan robotlar kullanılır. Bu robotların çalışırken odada insan bulunmamasının nedeni nedir?', 'UV-C ışığının deri ve gözlere zarar vermesi', ['Robotların insanları algılayacak sensörü olmaması', 'UV-C ışığının yalnız karanlıkta yayılabilmesi', 'İnsanların robotun pilini boşaltması'], 'UV-C mikroorganizmaların genetik malzemesini bozarak dezenfeksiyon yapar; aynı etki insan derisinde yanığa ve gözde hasara yol açar.'),
  ('Robotik cerrahi sistemlerinin cerrahın elindeki çok küçük istemsiz titremeleri alet ucuna aktarmaması hangi işlemle sağlanır?', 'Yüksek frekanslı hareketleri süzen filtreleme', ['Aletin hızını sürekli artırma', 'Kamera görüntüsünü büyütme', 'Kolları daha ağır malzemeden yapma'], 'El titremesi istemli hareketlere göre daha yüksek frekanslıdır; alçak geçiren filtre bu bileşenleri ayıklarken cerrahın asıl hareketini korur.'),
  ('1999\'da Sony\'nin piyasaya sürdüğü, sahibini tanıyıp zamanla "davranış geliştiren" eğlence amaçlı robot köpeğin adı nedir?', 'AIBO', ['Paro', 'Pepper', 'Kismet'], 'AIBO, tüketicilere yönelik ilk gelişmiş eğlence robotlarındandır; dört bacağı, kamerası ve dokunma sensörleriyle bir köpek gibi davranacak biçimde tasarlandı.'),
  ('Sürü robotiği yaklaşımının temel özelliği hangisidir?', 'Merkezi yönetici olmadan yerel kurallarla ortak davranış', ['Tek bir çok güçlü robotun bütün işleri yapması', 'Her robotun bir insan tarafından ayrı ayrı yönetilmesi', 'Robotların birbirinden hiç bilgi almaması'], 'Karınca ve arı kolonilerinden esinlenen sürü robotiğinde her robot yalnız komşularına göre davranır; birkaç robot bozulsa da sistem çalışmaya devam eder.'),
  ('Yılan biçimli robotların arama-kurtarma çalışmalarında dikkat çekmesinin başlıca nedeni nedir?', 'Enkazdaki dar ve kıvrımlı boşluklardan geçebilmeleri', ['Uçabilmeleri', 'Çok ağır yükleri hızla taşıyabilmeleri', 'Yalnız düz asfaltta hareket edebilmeleri'], 'Çok sayıda eklemden oluşan ince gövde, tekerlekli ya da bacaklı robotların giremeyeceği borulara ve çatlaklara girebilir.'),
  ('Robot sumo yarışmalarında bir robotun kazanmak için ne yapması gerekir?', 'Rakibi dairesel ringin dışına itmek', ['Rakibin bataryasını sökmek', 'Labirentin çıkışını ilk bulmak', 'Belirli bir çizgiyi en hızlı izlemek'], 'Robotlar dairesel bir ringde karşı karşıya gelir; rakibini ring dışına çıkaran kazanır. Bu yüzden düşük ağırlık merkezi, çekiş ve rakibi algılayan sensörler önemlidir.'),
  ('Robot yazılımında yaygın kullanılan ROS (Robot Operating System) hakkında hangisi doğrudur?', 'İşletim sistemi üzerinde çalışan açık kaynaklı bir ara katmandır', ['Yalnız tek bir şirketin robotlarında çalışan kapalı bir işletim sistemi çekirdeğidir', 'Robotların pillerini yöneten bir donanım kartıdır', 'Yalnız robot yarışmalarında kullanılan bir puanlama programıdır'], 'Adına karşın ROS, Linux gibi bir işletim sisteminin üzerinde çalışır; süreçler arası iletişim, sürücüler, görselleştirme ve simülasyon araçları sağlar.'),
  ('Robot çim biçme makinelerinin çoğu bahçenin sınırını nasıl algılar?', 'Kenara döşenen sinyal telinin manyetik alanını algılayarak', ['Çimin rengini uydudan izleyerek', 'Bahçe duvarlarına çarpınca durarak', 'Komşunun Wi-Fi sinyalini ölçerek'], 'Şarj istasyonuna bağlı sınır teli bir akım sinyali taşır; robot telin hangi tarafında olduğunu manyetik alanın yönünden anlar ve dışarı çıkmaz.'),
  ('Otomatik bir bahçe sulama sisteminde zamanlayıcının yanına toprak nem sensörü eklenmesinin en önemli yararı nedir?', 'Toprak nemliyken gereksiz sulamayı önlemesi', ['Bitkilerin daha hızlı büyümesi için suyu ısıtması', 'Sulamanın yalnız gece saatlerinde yapılmasını zorunlu kılması', 'Su borularındaki basıncı iki katına çıkarması'], 'Yalnız zamanlayıcıya bağlı sistem yağmurdan sonra da sular. Nem sensörü denetimi kapalı çevrime çevirir ve gerçek ihtiyaca göre çalıştırır.'),
  ('Otomatik panjur sistemlerine rüzgâr sensörü eklenmesinin amacı nedir?', 'Güçlü rüzgârda dış panjurları toplayıp korumak', ['Panjurların rengini rüzgâra göre değiştirmek', 'Rüzgâr enerjisiyle panjurları şarj etmek', 'Rüzgâr yönüne göre evin adresini belirlemek'], 'Dış güneş kırıcılar ve tenteler kuvvetli rüzgârda zarar görebilir; anemometre belirli bir hızı algılayınca sistem bunları güvenli konuma getirir.'),
  ('Modern süt sağım robotlarında inek sağılmak için istediği saatte bölmeye girer. Robot meme başlarının yerini nasıl bulur?', 'Lazer ya da 3B kamerayla meme başlarını bularak', ['İneğin sesini dinleyerek', 'İneğin kulağındaki numarayı okuyarak meme konumunu tablodan seçerek', 'İneğin ağırlığını tartarak'], 'Robot kol, görüntü sensörleriyle her ineğin meme başlarının konumunu bulur ve sağım başlıklarını takar; inek kimliği ise genellikle RFID tasmasıyla tanınır.'),
  ('Amazon\'un 2012\'de satın aldığı Kiva Systems\'in depo robotlarının çalışma ilkesi hangisidir?', 'Robotlar rafı kaldırıp sabit duran toplayıcıya getirir', ['Robotlar ürünleri tek tek raflardan kollarıyla alıp kargolar', 'Toplayıcılar robotlara binip raf aralarında gezer', 'Robotlar depoyu yalnız gece temizler'], '\'Ürünü insana getir\' yaklaşımında çalışan yürümez; robotlar zemindeki işaretleri izleyerek ilgili rafı kaldırıp istasyona taşır. Bu, toplama verimliliğini büyük ölçüde artırır.'),
  ('Bir dağıtım merkezinde paketlerin barkodları okunup her biri, üzerinde ilerlediği konveyörden kendi teslimat bölgesinin oluğuna otomatik olarak yönlendiriliyor. Bu sisteme genel olarak ne ad verilir?', 'Otomatik ayıklama (sorter) sistemi', ['Paletleme robotu', 'Kartezyen portal kaynak ve kesim hücresi', 'Dijital ikiz'], 'Ayıklayıcılar saatte binlerce paketi okuyup çapraz bant, eğimli tepsi ya da itici kollarla doğru çıkışa yönlendirir.'),
  ('Bir paletleme robotunun programında kutuların her katmanda bir önceki katmana göre çaprazlanarak dizilmesinin amacı nedir?', 'Yükün kilitlenip taşıma sırasında dağılmasını önlemek', ['Kutuların daha hızlı açılmasını sağlamak', 'Robotun daha az enerji harcamasını ve daha hızlı çalışmasını garanti etmek', 'Paletin rengini değiştirmek'], 'Katmanların örgü gibi bindirilmesi, alttaki kutuların birbirine bağlanmasını sağlar; palet dengeli ve sağlam olur.'),
  ('CNC programlarında G00 ile G01 komutları arasındaki fark hangisidir?', 'G00 kesmeden hızlı konumlanır, G01 ilerleme hızıyla keser', ['G00 iş milini durdurur, G01 soğutma sıvısını açar', 'G00 programı bitirir, G01 programı baştan başlatır', 'G00 dairesel, G01 sarmal hareket yapar'], 'G00 boşta en yüksek hızla konum değiştirmek içindir; G01 ise F ile verilen ilerleme hızında doğrusal interpolasyon yapar ve kesme bu komutla yapılır.'),
  ('Torna ile freze tezgâhı arasındaki temel fark hangisidir?', 'Tornada iş parçası döner, frezede kesici takım döner', ['Tornada hiç kesici takım yoktur', 'Freze yalnız ahşap, torna yalnız metal ve plastik malzemeleri işler', 'Torna yalnız düz yüzey, freze yalnız silindir üretir'], 'Tornada iş parçası ayna üzerinde döner ve sabit takım silindirik biçimler çıkarır. Frezede dönen çok ağızlı takım sabit ya da hareketli parçadan talaş kaldırır.'),
  ('CAD/CAM sürecinde CAM yazılımının temel görevi nedir?', 'Modelden takım yollarını ve tezgâh kodunu üretmek', ['Parçanın üç boyutlu modelini sıfırdan çizmek', 'Fabrikanın muhasebe kayıtlarını tutmak', 'Operatörlerin vardiya çizelgesini hazırlamak'], 'CAD\'de parça tasarlanır; CAM bu modeli alıp takım, kesme derinliği ve ilerleme seçimleriyle takım yollarını hesaplar ve tezgâha uygun G-kodunu üretir.'),
  ('Bir endüstriyel robotun, operatörün öğretme cihazıyla robotu adım adım istenen noktalara götürüp bu noktaları kaydetmesiyle programlanmasına ne ad verilir?', 'Çevrim içi öğretme (teach-in) programlama', ['Çevrim dışı (offline) simülasyonla programlama', 'Görsel servo denetim', 'Sürü programlama'], 'Öğretme yöntemi kolay ve gerçek hücreye uygundur; ancak programlama sırasında robot ve hat üretim dışı kalır.'),
  ('Bir kaynak robotunda torç ucunun iki nokta arasında tam düz bir çizgi izlemesi gerekiyor. Hangi hareket türü seçilmelidir?', 'Doğrusal (Kartezyen) hareket', ['Eklem (noktadan noktaya) hareketi', 'Rastgele örnekleme hareketi', 'Hızlı konumlama hareketi'], 'Eklem hareketinde her eklem kendi hedef açısına gider ve uç eğri bir yol izler. Doğrusal harekette denetleyici, ucun düz çizgide kalması için eklemleri sürekli eşgüdümler.'),
  ('Bir al-yerleştir programında robot ara noktalarda tam durmak yerine köşeleri yumuşakça yuvarlayarak geçiyor. Bu ayarın başlıca yararı nedir?', 'Çevrim süresini kısaltması ve sarsıntıyı azaltması', ['Konum doğruluğunu bütün noktalarda artırması', 'Robotun hiç enerji harcamaması', 'Tutucunun daha sıkı kavraması'], 'Her ara noktada durup kalkmak zaman kaybettirir ve ani ivmeler yaratır. Ara noktaların hassas olması gerekmiyorsa köşe yumuşatma hızı ve akıcılığı artırır.'),
  ('İşbirlikçi robotlarda operatörün robot kolunu eliyle tutup istenen yola götürmesi ve robotun bu hareketi kaydetmesi hangi programlama yöntemidir?', 'Elle kılavuzlayarak öğretme', ['Çevrim dışı CAD/CAM programlama', 'G-kodu ile programlama', 'Merdiven diyagramıyla programlama'], 'Kuvvet algılayan cobotlar kolun elle sürüklenmesine izin verir; bu, programlama bilgisi az olan kullanıcılar için hızlı bir yöntemdir.'),
  ('Bir robot programında parça alınmadan önce parçanın birkaç santimetre üstünde bir "yaklaşma noktasına" gidilmesinin amacı nedir?', 'Kontrollü, dik bir inişle çarpışmayı önlemek', ['Robotun pilini şarj etmek', 'Kameranın renk ayarını yapmak', 'Programın daha uzun görünmesini sağlamak'], 'Doğrudan uzak bir noktadan parçaya gitmek, tutucunun parçaya ya da fikstüre yandan çarpmasına yol açabilir. Yaklaşma noktasından düz ve yavaş iniş güvenli kavrama sağlar.'),
  ('Dokunma duyusuna dayalı geri bildirim teknolojilerine, örneğin uzaktan yönetilen bir robot kolun karşılaştığı direnci operatörün eline kuvvet olarak yansıtan sistemlere genel olarak ne ad verilir?', 'Haptik teknoloji', ['Telemetri ve uzaktan ölçüm', 'Holografi', 'Stereofoni'], 'Haptik sistemler operatörün nesnenin sertliğini ve temasını hissetmesini sağlar; uzaktan montaj ve cerrahi gibi işlerde kazayla aşırı kuvvet uygulanmasını önler.'),
  ('Bir kişinin uzaktaki bir toplantıya ekranlı ve tekerlekli bir robot aracılığıyla katılıp odada dolaşabilmesini sağlayan sistemlere ne ad verilir?', 'Tele-varlık (telepresence) robotları', ['Endüstriyel kaynak ve boya robotları', 'Paletleme robotları', 'Sürü robotları'], 'Tele-varlık robotları kullanıcının görüntüsünü ve sesini taşır, onun gözü ve kulağı olarak uzaktaki ortamda hareket eder.'),
  ('Bir teraziyle aynı nesne on kez tartılıp ortalama alındığında hangi tür hata azalır, hangisi aynı kalır?', 'Rastgele hata azalır, sistematik hata aynı kalır', ['Sistematik hata azalır, rastgele hata aynı kalır', 'İki hata türü de tamamen ortadan kalkar', 'İki hata türü de iki katına çıkar'], 'Rastgele hatalar ortalamada birbirini götürür. Teraziden kaynaklanan sabit bir sapma ise her ölçümde aynı olduğundan ortalamaya aynen geçer; onu yalnız kalibrasyon giderir.'),
  ('Analog ibreli bir göstergenin okunurken ibreye yandan bakılması hangi tür ölçüm hatasına yol açar?', 'Paralaks hatası', ['Örtüşme hatası', 'Nicemleme hatası', 'Yükleme hatası'], 'İbre ile ölçek farklı düzlemlerde olduğundan eğik bakışta ibre ölçeğin başka bir çizgisinin üstündeymiş gibi görünür. Bazı göstergelerde ölçeğin altına ayna konarak bu önlenir.'),
  ('Ev robotlarının kamera ve mikrofonlarla sürekli veri toplaması konusundaki en yerinde kaygı hangisidir?', 'Ev içi özel verilerin izinsiz saklanıp paylaşılması', ['Robotların ev eşyalarının rengini soldurması', 'Robotların elektrik tesisatını her zaman yakması', 'Robotların internete hiç bağlanamaması'], 'Ev içi haritalar, görüntüler ve sesler kişisel veri niteliğindedir. Bu verilerin nerede tutulduğu, kimle paylaşıldığı ve ne kadar saklandığı kullanıcıya açıkça bildirilmelidir.'),
  ('Yapay zekâ ve robotik etik ilkelerinde sıkça geçen "durdurulabilirlik" kavramı neyi gerektirir?', 'İnsanın robotu her an güvenle durdurabilmesini', ['Robotun hiçbir zaman dinlenmemesini', 'Robotun kendi kendini kapatmayı reddedebilmesini', 'Robotun yalnız kablosuz çalışmasını'], 'Bir robotun beklenmeyen davranışında acil durdurma ve güvenli duruşa geçme olanağı, hem güvenlik standartlarının hem de etik çerçevelerin temel isteğidir.'),
  ('Yatay uzanmış bir robot kolu, omuz ekleminden 0,8 m uzakta 5 kg\'lık bir yük tutuyor. Kolun kendi ağırlığı ihmal edilir ve g = 10 m/s² alınırsa omuz ekleminin yükü tutmak için sağlaması gereken tork kaç N·m\'dir?', '40 N·m', ['4 N·m', '50 N·m', '6,25 N·m'], 'Tork = kuvvet × moment kolu = (5 × 10) N × 0,8 m = 40 N·m. Yük uca doğru uzaklaştıkça gereken tork doğrusal olarak artar.'),
  ('Dakikada 3000 devir dönen bir motor 50:1 oranlı bir redüktörle bir robot eklemine bağlanıyor. Eklem en çok dakikada kaç devir dönebilir?', '60 d/d', ['150 d/d', '6 d/d', '600 d/d'], 'Redüktör hızı oran kadar düşürür: 3000 ÷ 50 = 60 d/d. Karşılığında tork aynı oranda (kayıplar hariç) artar.'),
  ('Bir robot hücresi her parçayı 6 saniyelik bir çevrimde işliyor. Kesintisiz çalışırsa bir saatte kaç parça işler?', '600', ['360', '100', '3600'], 'Bir saat 3600 saniyedir; 3600 ÷ 6 = 600 parça.'),
  ('Bir konveyör 0,5 m/s hızla ilerliyor. Ürünün konumu kameranın altındayken ölçülüyor, robotun alma noktası ise kameradan 1,5 m ileride. Robot ürünü almak için ölçümden sonra kaç saniye sonra hazır olmalıdır?', '3 s', ['0,75 s', '1,5 s', '0,33 s'], 'Süre = yol ÷ hız = 1,5 ÷ 0,5 = 3 s. Konveyör izleme yazılımı bu hesabı enkoder sayımıyla sürekli günceller.'),
  ('Boya robotlarının motor ve elektrik donanımlarının özel olarak patlamaya karşı korumalı tasarlanmasının nedeni nedir?', 'Çözücü buharlarının kıvılcımla tutuşabilmesi', ['Boyanın robotun rengini değiştirmesi', 'Boya robotlarının su altında çalışması', 'Boyanın elektriği çok iyi iletip motorları soğutması'], 'Çözücü buharı ve boya sisi yanıcı bir ortam oluşturur. Basınçlandırılmış gövdeler ve kıvılcım çıkarmayan donanımlar tutuşma riskini ortadan kaldırır.'),
  ('Bir robotun CNC tezgâhına ham parçayı yükleyip işlenmiş parçayı alması ve böylece tezgâhın gece de insansız çalışabilmesi hangi robot uygulamasıdır?', 'Makine besleme', ['Ark kaynağı', 'Elektrostatik toz boyama', 'Dikiş izleme'], 'Makine besleme robotları tezgâhın boşta beklediği süreyi azaltır; özellikle tekrarlı ve uzun süreli üretimlerde verimliliği artırır.'),
  ('Gaz altı ark kaynağı yapan bir robot torcunda sürekli beslenen telin yanı sıra koruyucu gaz da üflenir. Gazın görevi nedir?', 'Erimiş banyoyu havadaki oksijen ve azottan korumak', ['Torcu soğutup kaynağı engellemek', 'Parçayı boyamak', 'Kaynak dikişini mıknatıslamak'], 'Havadaki gazlar erimiş metale karışırsa gözenek ve gevreklik oluşur. Argon ya da karbondioksit gibi koruyucu gazlar banyonun çevresinde koruyucu bir örtü oluşturur.'),
  ('Endüstriyel robotların eklemlerinde elektrik kesildiğinde devreye giren elektromanyetik frenler bulunur. Bunun temel amacı nedir?', 'Güç kesilince kolun ağırlığıyla düşmesini önlemek', ['Robotun daha hızlı hareket etmesini sağlamak', 'Motorların soğumasını hızlandırmak', 'Robotun elektrik faturasını azaltmak'], 'Bu frenler yay baskılıdır ve enerji kesilince kendiliğinden kilitlenir; böylece acil durdurma ya da kesintide kol olduğu yerde kalır.'),
  ('Bir robot kolunun ani başlayıp durmasının (sarsıntılı hareketin) yol açtığı sorunlardan biri hangisidir?', 'Titreşim, konum hatası ve mekanik yıpranma', ['Robotun boyasının solması', 'Kablolarının kısalması', 'Kameranın çözünürlüğünün artması'], 'İvmedeki ani değişimler (sarsıntı) kolda ve taşınan yükte salınımlar uyarır; yumuşak hız profilleri bu titreşimleri ve dişli aşınmasını azaltır.'),
  ('Pek çok endüstriyel robot kontrolcüsünde acil durdurma sonrası robotu yeniden başlatmadan önce hata kaydının incelenmesi önerilir. Bunun temel nedeni hangisidir?', 'Nedeni anlamadan yeniden başlatmanın tehlikeyi yinelemesi', ['Hata kaydının robotun hızını artırması', 'Kaydın silinmesinin robotu bozması', 'Kaydın yalnız yıllık bakımda okunabilmesi'], 'Acil durdurma bir belirtidir; altta yatan sorun (çarpışma, sensör arızası, yanlış program) giderilmeden çalışmaya dönmek kazayı yineleyebilir.'),
  ('Ölçtüğü değeri kendi içinde sayısallaştırıp kalibrasyon düzeltmelerini uygulayan, kendi arızasını tanılayıp sonucu sayısal haberleşmeyle bildiren sensörlere genel olarak ne ad verilir?', 'Akıllı sensör', ['Pasif sensör', 'Analog sensör', 'Mekanik sensör'], 'Akıllı sensörler mikrodenetleyici ve haberleşme arayüzü içerir; denetleyicinin yükünü azaltır ve bakım için tanı bilgisi sunar.'),
  ('Rüzgâr hızını ölçen, rüzgârda dönen kaplı ya da pervaneli aletlere ne ad verilir?', 'Anemometre', ['Barometre', 'Higrometre', 'Pluviyometre'], 'Kaplı anemometrede rüzgâr hızı arttıkça dönme hızı artar; dönme bir enkoder ya da mıknatıslı sensörle sayılarak hız hesaplanır.'),
  ('Bir sensör sinyalinin üstüne binmiş gürültüyü azaltmak için ardışık son 5 ölçümün ortalamasını çıkış olarak kullanan basit sayısal filtreye ne ad verilir?', 'Hareketli ortalama filtresi', ['Yüksek geçiren türev filtresi', 'Kalman yumuşatıcısı', 'Fourier dönüşümü'], 'Hareketli ortalama hızlı rastgele dalgalanmaları bastırır; karşılığında sinyaldeki gerçek değişimlere biraz gecikmeyle tepki verir.'),
  ('Sıvı akışının olup olmadığını algılayıp pompa kuru çalışırsa onu durdurmak için borulara takılan, akışla itilen bir paleti olan basit anahtara ne ad verilir?', 'Akış anahtarı', ['Basınç düşürücü', 'Termostat', 'Hız regülatörü'], 'Akış belirli bir debinin altına düşünce palet geri döner ve kontağı açar; denetleyici bunu pompayı korumak için kullanır.'),
  ('Endüstriyel bir kamerada her ürünün geçtiği anı algılamak için bir fotoelektrik sensör kullanılıyor ve kamera bu sensörün sinyaliyle görüntü alıyor. Bu kullanımın amacı nedir?', 'Görüntünün ürün doğru yerdeyken alınması', ['Kameranın renk ayarını yapmak', 'Ürünlerin ağırlığını ölçmek', 'Konveyörün hızını iki katına çıkarmak'], 'Tetikleme sensörü ürünün görüş alanının ortasına geldiği anı bildirir; böylece her görüntüde ürün aynı yerde olur ve analiz güvenilir yapılır.'),
  ('Bir sensörün katalogunda "IP67" koruma sınıfı yazıyor. Bu değer neyi anlatır?', 'Toza tam korumalı ve geçici suya dayanıklı olduğunu', ['Sensörün internet adresinin 67 olduğunu', 'Sensörün 67 °C\'ye kadar çalıştığını', 'Sensörün 67 mA akım çektiğini'], 'IP kodundaki ilk rakam katı cisim ve toza, ikinci rakam suya karşı korumayı gösterir. 6 toza tam koruma, 7 belirli derinlikte geçici daldırmaya dayanıklılık anlamına gelir.'),
  ('Basit robotlarda kullanılan, iki ucundaki temas yayının engele değince kapanması esasına dayanan "bıyık" (whisker) sensörleri hangi tür sensörlerdendir?', 'Dokunma (temas) sensörü', ['Mesafe ölçen optik sensör', 'Sıcaklık sensörü', 'Gaz sensörü'], 'Bıyık sensörleri, kedilerin bıyıklarından esinlenen basit temas anahtarlarıdır; engel ancak dokunulduğunda algılanır.'),
  ('Gece görüş kameralarının bazılarının kızılötesi LED\'lerle ortamı aydınlatmasının nedeni nedir?', 'Görünmez bu ışığı kamera sensörünün algılayabilmesi', ['Kızılötesi ışığın nesneleri ısıtarak görünür kılması', 'Kızılötesi ışığın duvarların arkasını göstermesi', 'Kameranın renkleri daha canlı kaydetmesi'], 'Silisyum görüntü sensörleri yakın kızılötesine duyarlıdır. Görünmez aydınlatma sayesinde ortam karanlık kalırken kamera net görüntü alabilir.'),
  ('Fabrikalarda baş üstü vidalama gibi işlerde işçilerin kollarını destekleyen, motor yerine yaylarla çalışan giyilebilir düzeneklere ne ad verilir?', 'Pasif dış iskelet', ['Aktif protez', 'Teleoperasyon kolu', 'Mobil manipülatör'], 'Pasif dış iskeletler yay ya da elastik elemanlarla kolun ağırlığını kısmen dengeler; pil ve motor gerektirmediği için hafif ve ucuzdur.'),
  ('Bir mobil tabanın üzerine robot kol monte edilerek oluşturulan, hem dolaşıp hem de nesneleri işleyebilen robotlara ne ad verilir?', 'Mobil manipülatör', ['Delta robot', 'Kartezyen portal', 'Sabit hücre robotu'], 'Mobil manipülatörler, sabit robotun erişimini fabrikanın tamamına yayar; ancak tabanın konum hatası kolun hassasiyetine eklendiği için ek görsel düzeltme gerekebilir.'),
  ('Kaldırımda yavaşça ilerleyerek paket ya da yemek teslim eden küçük otonom robotların hızlarının düşük tutulmasının başlıca nedeni nedir?', 'Yayalar arasında güvenli durma mesafesini korumak', ['Bataryalarının hızlı gidince patlaması', 'Kameralarının yalnız düşük hızda çalışması', 'Kaldırımların hıza göre ücret alması'], 'Yavaş hareket, beklenmedik bir yaya ya da çocuk karşısında robotun kısa mesafede durmasını ve çarpışma etkisinin küçük kalmasını sağlar.'),
  ('Cam silme robotlarının dik camlarda düşmeden durabilmesi en çok neye dayanır?', 'Fanın oluşturduğu vakumla cama yapışmaya', ['Camın statik elektrikle robotu çekmesine', 'Robotun çok hafif olup havada süzülmesine', 'Camdaki su damlalarının yüzey gerilimine'], 'Fan robotun altındaki havayı emerek düşük basınç oluşturur; dışarıdaki atmosfer basıncı robotu cama bastırır. Ayrıca güvenlik ipi kullanılır.'),
  ('Havuz temizleme robotlarının duvarlara tırmanabilmesinin nedeni hangisidir?', 'Pompanın su emerek onu yüzeye bastırması', ['Robotun içinin helyumla dolu olması', 'Havuz duvarlarının mıknatıslı olması', 'Robotun çok hızlı dönerek duvara yapışması'], 'Robotun altından emilen su, gövdenin altında düşük basınç oluşturur; bu da robotu yüzeye bastırır ve paletleri ya da fırçaları çekiş sağlar.'),
  ('Robot kollarda kablo ve hortumların eklem hareketleriyle sürtünüp kopmasını önlemek için kullanılan, zincir halkalarından oluşan kılavuzlara ne ad verilir?', 'Kablo taşıyıcı zincir', ['Triger kayışı', 'Sonsuz vida ve karşılık dişli', 'Harmonik dişli'], 'Kablo taşıyıcılar kabloları belirli bir bükülme yarıçapında tutarak hareket boyunca düzenli taşır; kabloların yorulup kopmasını geciktirir.'),
  ('Bir konveyörde hızla geçen şişelerin dik durup durmadığı tek tek kontrol ediliyor; devrik şişeler bir hava üfleyiciyle hattan atılıyor. Bu düzenekte aktüatör hangisidir?', 'Basınçlı hava memesi', ['Şişeleri gören kamera', 'Görüntü işleme yazılımı', 'Konveyör enkoderi'], 'Kamera ve yazılım algılama ve karar kısmını oluşturur; şişeyi fiziksel olarak hattan çıkaran üfleyici ise eylemi yapan aktüatördür.'),
  ('Gıda üretiminde çalışan robotların yüzeylerinin pürüzsüz, kolay temizlenebilir ve gıdaya uygun yağlayıcılarla yapılmasının temel nedeni nedir?', 'Hijyen sağlayıp bakteri birikimini önlemek', ['Robotun daha hızlı hareket etmesini sağlamak', 'Robotun daha az elektrik harcamasını sağlamak', 'Robotun rengini korumak'], 'Girinti ve vidalar kir ve bakteri barındırabilir; yüzeylerin yıkamaya uygun olması ve olası sızıntıların gıdaya zararsız olması gerekir.'),
  ('Acil durdurma devrelerinin çoğunlukla iki ayrı kanalla (çift kablo ve çift kontakla) kurulmasının nedeni nedir?', 'Tek kablo ya da kontak arızasının durdurmayı engellememesi', ['Makinenin iki kat hızlı durması', 'Devrenin daha az elektrik harcaması', 'Düğmenin iki farklı renkte yanabilmesi'], 'Kanallardan biri kısa devre olsa ya da kontak yapışsa bile diğeri durdurmayı sağlar; denetleyici iki kanalın uyumsuzluğunu da hata olarak algılar.'),
  ('Tekerlekli bir robot ile bacaklı bir robotun aynı düz zeminde aynı yolu alırken harcadığı enerji karşılaştırıldığında genellikle ne görülür?', 'Tekerlekli robot çok daha az enerji harcar', ['Bacaklı robot hiç enerji harcamaz', 'İkisi her zaman tam olarak aynı enerjiyi harcar', 'Tekerlekli robot düz zeminde ilerleyemez'], 'Tekerlek düz zeminde yuvarlanırken az kayıp yaşar; bacaklarda ise her adımda gövdenin yükselip alçalması ve bacakların hızlandırılıp yavaşlatılması enerji tüketir.'),
  ('Bazı hibrit robotlar hem bacak hem tekerlek taşır. Bu tasarımın amacı en iyi nasıl açıklanır?', 'Tekerleğin verimini ve bacağın çevikliğini birleştirmek', ['Robotun ağırlığını iki katına çıkarmak', 'Robotun hiç sensör kullanmaması', 'Robotu yalnız merdivende kullanmak'], 'Tekerlekler düz zeminde hızlı ve verimlidir, bacaklar ise basamak ve engellerde üstündür; ikisinin birleşimi farklı arazilerde esneklik sağlar.'),
  ('Bir lidar veya derinlik kamerasının çıktısı olan ve her biri üç boyutlu koordinata sahip milyonlarca noktadan oluşan veri yapısına ne ad verilir?', 'Nokta bulutu', ['Piksel matrisi', 'Ses dalgası', 'Doluluk tablosu'], 'Nokta bulutu, sahnedeki yüzeylerin üç boyutlu örnekleridir; nesne tanıma, haritalama ve tersine mühendislikte kullanılır.'),
  ('Büyük endüstriyel robotların omuz ekseninde sıklıkla bir yay ya da gazlı silindirden oluşan dengeleme düzeneği bulunur. Bunun amacı nedir?', 'Kol ağırlığının momentini dengeleyip motoru rahatlatmak', ['Robotun daha yüksek sesle çalışması', 'Kolun renk değiştirmesi', 'Robotun kablolarını düzenlemek'], 'Kol öne uzandıkça ağırlığı omuzda büyük bir moment yaratır. Dengeleyici bu momentin bir kısmını karşılayarak daha küçük motor ve redüktör kullanılmasını sağlar.'),
  ('Bir otomatik otopark sisteminde araç girişte bırakılıyor ve robotik bir platform aracı alıp çok katlı rafların birine yerleştiriyor. Bu sistemin geleneksel otoparka göre başlıca üstünlüğü nedir?', 'Aynı alana daha çok araç sığdırması', ['Araçların daha hızlı eskimesi', 'Sürücülerin park etmeyi öğrenmek zorunda kalması', 'Otoparkın elektrik kullanmaması'], 'Rampa ve manevra alanına gerek olmadığından araçlar sıkışık biçimde istiflenir; ayrıca insanlar araç depolama alanına girmediği için güvenlik artar.'),
  ('Bir depoda çalışan otonom forkliftin önüne monte edilen güvenlik lazer tarayıcısında iki ayrı alan tanımlanmıştır: dıştaki "uyarı alanı" ve içteki "koruma alanı". Bu ayrımın amacı nedir?', 'Uyarı alanında yavaşlayıp koruma alanında tamamen durmak', ['İki alanın da hiçbir işlevi yoktur', 'Uyarı alanında hızlanıp koruma alanında yalnızca sesli uyarı vermek', 'Alanlardan birinin yalnız gece çalışması'], 'Kademeli tepki, gereksiz duruşları azaltırken güvenliği korur: biri uzaktaysa araç yavaşlar, çok yaklaşırsa hemen durur.'),
  ('Bir AGV\'nin hızı arttıkça güvenlik tarayıcısının koruma alanının da büyütülmesi gerekir. Bunun nedeni nedir?', 'Hızlı giden araç durana kadar daha uzun yol alır', ['Hız arttıkça tarayıcının ışığı zayıflar ve menzili kısalır', 'Yavaş araçlar hiç durmak zorunda değildir', 'Koruma alanı yalnız aracın rengine bağlıdır'], 'Durma mesafesi hızla birlikte artar; koruma alanı, algılama anından tam duruşa kadar aracın alacağı yoldan büyük olmalıdır.'),
  ('Bir hasar tespit drone\'u köprü ayaklarını tararken her fotoğrafın konumunu ve yönelimini kaydediyor. Sonradan bu fotoğraflardan yapının üç boyutlu modelinin çıkarılmasını sağlayan yöntem hangisidir?', 'Fotogrametri', ['Eşikleme', 'Ses kaydı', 'Termografi'], 'Fotogrametri, farklı açılardan çekilmiş örtüşen fotoğraflardaki ortak noktaları eşleştirerek üç boyutlu geometri hesaplar; köprü ve bina denetiminde yaygın kullanılır.'),
  ('Bir robot projesinde "sistem entegratörü" olarak adlandırılan firmanın tipik görevi nedir?', 'Robotu, tutucuyu ve güvenliği birleştirip hücre kurmak', ['Robotun motorlarını sıfırdan üretmek', 'Robot için hammadde madeni çıkarmak', 'Robotun reklam filmini çekmek'], 'Robot üreticisi kolu sağlar; entegratör uygulamaya özel tutucu, fikstür, güvenlik, programlama ve devreye almayı üstlenerek anahtar teslim bir çözüm kurar.'),
  ('Bir fabrika yeni robot hücresinin yatırımı 600.000 TL, yılda sağladığı tasarruf 200.000 TL olarak hesaplanıyor. Basit geri ödeme süresi kaç yıldır?', '3 yıl', ['2 yıl', '4 yıl', '6 yıl'], 'Geri ödeme süresi = yatırım ÷ yıllık tasarruf = 600.000 ÷ 200.000 = 3 yıl. Gerçek değerlendirmede bakım ve finansman giderleri de eklenir.'),
  ('Robot destekli bir montaj hattında tek bir yavaş istasyon bütün hattın hızını belirliyor. Bu istasyona ne ad verilir?', 'Darboğaz', ['Tampon stok', 'Ölü bant', 'Tetikleme noktası'], 'Hattın çıkışı en yavaş istasyonun hızını aşamaz. Darboğazı hızlandırmak bütün hattın üretimini artırırken diğer istasyonları hızlandırmak işe yaramaz.'),
  ('İki ardışık robot hücresi arasına konan ara stok alanının (tampon) üretim hattına yararı nedir?', 'Bir hücre kısa süre dursa da ötekinin çalışabilmesi', ['Robotların enerji tüketiminin sıfırlanması', 'Ürünlerin kalitesinin kendiliğinden artması', 'Hücrelerin birbirine kablosuz bağlanması'], 'Tampon, kısa duruşların etkisini emer; önceki hücre arıza yaparken sonraki hücre tampondaki parçalarla bir süre daha üretim yapabilir.'),
  ('Bir elektrik motoru robotlarda hangi enerji dönüşümünü yapar?', 'Elektrik enerjisini hareket (mekanik) enerjisine', ['Hareket enerjisini elektrik enerjisine ve ısıya dönüştürür', 'Işık enerjisini ısı enerjisine', 'Kimyasal enerjiyi ses enerjisine'], 'Motor, sargılarından geçen akımın oluşturduğu manyetik kuvvetle mili döndürür. Tersini yapan, yani hareketi elektriğe çeviren aygıt jeneratördür.'),
  ('Hidrolik aktüatörlerde gücü iletmek için genellikle hangi akışkan kullanılır?', 'Özel hidrolik yağ', ['Basınçlı hava', 'Saf oksijen ya da azot gazı', 'Buhar'], 'Hidrolik sistemler sıkıştırılamaz bir sıvıyla, çoğunlukla madeni ya da sentetik yağla çalışır; yağ aynı zamanda parçaları yağlar ve korur.'),
  ('Havalimanı lavabolarındaki musluklar el altına uzatılınca kendiliğinden su akıtıyor. Bu musluklarda eli algılayan sensör genellikle hangisidir?', 'Kızılötesi yakınlık sensörü', ['Termokupl', 'Gerinim ölçer', 'Manyetometre'], 'Musluk kızılötesi ışık gönderir; el yaklaşınca yansıyan ışık alıcıya ulaşır ve bir solenoid vana suyu açar.'),
  ('Bir mikrodalga fırının kapısı açıldığı anda fırının çalışmayı durdurmasını sağlayan düzenek hangi güvenlik ilkesinin günlük hayattaki örneğidir?', 'Kapı kilitleme (interlock) anahtarı', ['Kalibrasyon', 'Örnekleme ve sayısallaştırma', 'Odometri'], 'Kapı anahtarları açılınca güç devresini keser; robot hücrelerindeki güvenlik kapıları da aynı ilkeyle robotu durdurur.'),
  ('Binalardaki otomatik yangın söndürme başlıklarında (sprinkler) içi sıvı dolu küçük bir cam ampul bulunur. Elektrik kullanmayan bu sistem nasıl çalışır?', 'Isınan sıvı genleşip ampulü kırar ve su akmaya başlar', ['Duman ampulün rengini değiştirip vanayı açar', 'Ampul ışık sensörü gibi alevi görüp elektrik üretir', 'Ampul her saat kendiliğinden kırılıp su verir'], 'Ampul hem sensör hem tetikleyici görevi görür: belirli sıcaklıkta içindeki sıvının genleşmesiyle kırılır ve tıkadığı su yolunu açar.'),
  ('Bir robot süpürgenin ön kısmındaki hareketli tampon, robot bir mobilyaya çarptığında ne işe yarar?', 'Çarpmayı içindeki anahtarlarla bildirir', ['Robotun pilini şarj eder', 'Robotun emme gücünü artırır', 'Robotun haritasını siler'], 'Tampon basit bir temas sensörüdür; çarpınca arkasındaki mikro anahtarlar kapanır ve robot geri çekilip başka yöne döner.'),
  ('Hobi servo motorlarından çıkan üç kablonun görevleri hangi seçenekte doğru verilmiştir?', 'Besleme (+), toprak (−) ve konum komutu sinyali', ['Üç ayrı motorun güç kabloları', 'Sıcaklık, nem ve basınç sensörlerinin sinyalleri', 'Ses, görüntü ve internet bağlantısı'], 'İki kablo motoru besler; üçüncüsü darbe genişliğiyle hedef açıyı bildiren sinyal hattıdır.'),
  ('Aşağıdakilerden hangisi otomasyona örnek değildir?', 'Elle çevrilen bir kahve değirmeni', ['Hava kararınca kendiliğinden yanan sokak lambası', 'Seviye düşünce kendiliğinden çalışan su pompası', 'Kapıya yaklaşınca açılan otomatik kapı'], 'Otomasyonda işlem, bir algılama ya da programa göre insan müdahalesi olmadan yürür. Elle çevrilen değirmende her hareketi insan yapar.'),
  ('İki sensörlü basit bir çizgi izleyen robotta sol sensör siyah çizgiyi görmeye başladığında robot ne yapmalıdır?', 'Çizgiye dönmek için sola doğru dönmelidir', ['Sağa doğru dönüp hızını artırmalıdır', 'Tamamen durmalıdır', 'Geri geri gitmelidir'], 'Sensörler çizginin iki yanındadır; çizgi sol sensörün altına kaydıysa robot sağa sapmıştır ve çizgiyi ortalamak için sola dönmelidir.'),
  ('Bir robotun parçalarını insan duyularıyla eşleştiren bir öğrenci aşağıdakilerden hangisinde yanlış eşleştirme yapmıştır?', 'Hoparlör – işitme', ['Kamera – görme', 'Basınç sensörü – dokunma', 'Gaz sensörü – koku alma'], 'Hoparlör ses üretir, yani bir çıkış (aktüatör) aygıtıdır. İşitme duyusuna karşılık gelen sensör mikrofondur.'),
  ('Alışveriş merkezlerindeki yürüyen merdivenlerin alt ve üst uçlarında bulunan kırmızı düğme ne işe yarar?', 'Tehlike anında merdiveni acil olarak durdurmak', ['Merdivenin hızını artırmak', 'Merdivenin yönünü her basışta ters çevirmek', 'Merdiveni aydınlatmak'], 'Acil durdurma düğmesi, bir giysi ya da ayak sıkıştığında merdivenin hemen durdurulmasını sağlar; makinelerdeki acil durdurma ilkesiyle aynıdır.'),
  ('Fabrikalarda ürünleri bir istasyondan diğerine sürekli taşıyan, motorla döndürülen kayış ya da makaralardan oluşan sisteme ne ad verilir?', 'Konveyör', ['Kompresör', 'Kondansatör', 'Kontaktör'], 'Konveyörler üretim hatlarının taşıma omurgasıdır; hızları genellikle bir motor sürücüsüyle ayarlanır ve sensörlerle ürünlerin konumu izlenir.'),
  ('Bir robot kolun, insan kolundaki omuz, dirsek ve bileğe benzeyen hareketli birleşim yerlerine genel olarak ne ad verilir?', 'Eklem', ['Kablo', 'Gövde kapağı', 'Taban plakası'], 'Eklemler bağları birbirine bağlar ve aralarında göreli harekete izin verir; her eklem genellikle bir motorla sürülür.'),
  ('Bir robotun pil seviyesi düşünce görevini yarıda bırakıp kendi şarj istasyonuna dönmesi, robotun hangi yeteneğine örnektir?', 'Kendi durumunu algılayıp buna göre karar verme', ['Uzaktan kumandayla yönetilme', 'Yalnız önceden kaydedilmiş hareketi tekrarlama', 'Elle çalıştırılma'], 'Robot hem dış dünyayı hem kendi iç durumunu (pil, sıcaklık gibi) izler; bu bilgilere göre görev önceliğini değiştirmesi özerk davranışın basit bir örneğidir.'),
  ('Bir robotun kızılötesi şarj istasyonunu bulması için istasyon ne yapar?', 'Kızılötesi işaret yayarak yön bulmasına yardım eder', ['Robotu mıknatısla kendine çeker', 'Robota telefonla haber verir', 'Robotun önüne ray döşer'], 'İstasyonun yaydığı kodlanmış kızılötesi işaretler robotun alıcılarına sol, sağ ya da orta bölgeden geldiğini bildirir; robot bu işaretleri izleyerek istasyona yanaşır.'),
  ('Bir fabrikada sıcaklık sensörünün ölçtüğü değeri gösteren, ayar değerini girmeye ve rölesiyle ısıtıcıyı açıp kapatmaya yarayan küçük pano cihazına ne ad verilir?', 'Proses denetleyici', ['Frekans sayacı ve osiloskop', 'Multimetre', 'Lehim istasyonu'], 'Pano tipi sıcaklık kontrol cihazları sensör girişini okur, PID ya da aç-kapa algoritmasıyla çıkış rölesini sürer; fırın ve kalıp ısıtmada yaygındır.'),
  ('Bir PLC\'nin dijital giriş kartına bağlanan bir düğmenin basılı olup olmadığını PLC nasıl anlar?', 'Girişteki gerilimin eşiğin üstünde ya da altında olmasından', ['Düğmenin rengini kameradan okuyarak', 'Düğmenin sıcaklığını ölçerek', 'Düğmeden gelen ses dalgasını analiz ederek'], 'Endüstride dijital girişler genellikle 24 V ile çalışır; belirli bir eşiğin üzerindeki gerilim \'1\', altındaki \'0\' olarak okunur.'),
  ('Bir robot hücresinde acil durdurma düğmesine basıldıktan sonra robot hemen hareket etmeye devam etmeyip düğme çekilip sıfırlanana kadar bekliyor. Bunun nedeni nedir?', 'Düğme kilitli kalır ve açılmadan makine başlamaz', ['Düğme robotun pilini boşaltır', 'Düğme robotun programını siler', 'Düğme yalnız ışıkları kapatır'], 'Acil durdurma düğmeleri basıldıktan sonra mekanik olarak kilitli kalır; tehlike giderilmeden makinenin yanlışlıkla çalışması böylece önlenir.'),
  ('Aşağıdaki sensörlerden hangisi temas olmadan ölçüm yapar?', 'Kızılötesi termometre', ['Mekanik sınır anahtarı', 'Çarpma tamponu', 'Bıyık (whisker) sensörü'], 'Kızılötesi termometre nesnenin yaydığı ışınımı uzaktan ölçer. Diğerleri ancak bir nesne fiziksel olarak dokunduğunda sinyal üretir.'),
  ('Bir robot kolu ile aynı işi yapan sabit, tek amaçlı bir makine (örneğin yalnız şişe kapağı kapatan düzenek) karşılaştırıldığında robotun en önemli üstünlüğü hangisidir?', 'Yeniden programlanıp başka işlerde kullanılabilmesi', ['Her zaman daha ucuz olması', 'Hiç bakım gerektirmemesi', 'Daha az yer kaplaması'], 'Tek amaçlı makineler kendi işinde çok hızlı ve ucuz olabilir; robot ise ürün ya da görev değişince yeni programla başka işlere uyarlanabilir.'),
  ('Bir robot kolu ile insan işçinin birlikte çalıştığı bir montaj hattında aşağıdaki görev paylaşımlarından hangisi en mantıklıdır?', 'Ağır ve tekrarlı işi robot, karar gerektiren işi insan yapar', ['Robot yalnız dinlenir, insan her işi yapar', 'İnsan ağır parçaları taşır, robot yalnız ekranı izler', 'Robot ve insan aynı anda aynı vidayı sıkar'], 'İşbirlikçi hatlarda robot yorulmadan yapılan, ergonomik açıdan zararlı işleri üstlenir; insan esneklik ve muhakeme gerektiren adımlarda kalır.'),
  ('Bir öğrencinin yaptığı robot, mesafe sensörünün okuduğu değer 20 cm\'nin altına düşünce duruyor. Robotun kartının bu karşılaştırmayı yapan parçası hangisidir?', 'Mikrodenetleyici', ['Motor', 'Pil ve güç düzenleyicisi', 'Tekerlek'], 'Sensör veriyi üretir, motor hareketi yapar; aradaki karar (\'20 cm\'den küçük mü?\') mikrodenetleyicide çalışan programda verilir.'),
  ('Bir robot programında "parça algılanmadıysa 5 saniye bekle, hâlâ yoksa operatöre uyarı ver" adımı bulunuyor. Bu adımın amacı nedir?', 'Beklenmeyen durumda sonsuza dek takılı kalmayı önlemek', ['Robotun daha hızlı çalışmasını sağlamak', 'Parçanın rengini değiştirmek', 'Robotu her zaman kapatmak'], 'Zaman aşımı denetimi, bir sensör ya da besleyici arızasında robotun sessizce beklemek yerine durumu bildirmesini sağlar; arıza süresi kısalır.'),
];
